window.AponarQuartet2Data={"q2":{"chapters.theme_bn":{"প্রসঙ্গ, পরোক্ষ কথা ও ভাষার সূক্ষ্ম পার্থক্য":"سیاق، بالواسطہ بات اور زبان کا باریک فرق","যুক্তি, বিকল্প দৃষ্টিকোণ ও মতামত গঠন":"دلیل، متبادل نقطہ نظر اور رائے کی تشکیل","অভিজ্ঞতা থেকে শেখা ও ভদ্রভাবে মতের পার্থক্য বলা":"تجربے سے سیکھنا اور شائستگی سے رائے کا فرق کہنا","কাজের মূল্যবোধ, সাক্ষাৎকার নেওয়া ও তথ্য সাজানো":"کام کی قدریں، انٹرویو لینا اور معلومات ترتیب دینا","ঘটনার মোড়, উপমা ও অনুভূতির পরিবর্তন পড়া":"واقعے کا موڑ، تشبیہ اور احساس کی تبدیلی پڑھنا","তুলনা, পরিবর্তনের প্রবণতা ও সীমিত সিদ্ধান্ত":"موازنہ، تبدیلی کا رجحان اور محدود فیصلہ"},"chapters.title_bn":{"অধ্যায় ৮ · পেশাদারিত্ব ও সাক্ষাৎকার":"باب 8 · پیشہ ورانہ پن اور انٹرویو","অধ্যায় ১০ · তথ্য দিয়ে সমাজ বোঝা":"باب 10 · معلومات سے معاشرہ سمجھنا","অধ্যায় ৯ · গল্প, অনুভূতি ও পর্যালোচনা":"باب 9 · کہانی، احساس اور جائزہ","অধ্যায় ১২ · চিন্তার পরিবর্তন ও সমাজ":"باب 12 · سوچ کی تبدیلی اور معاشرہ","অধ্যায় ১১ · শব্দের আড়ালের অর্থ":"باب 11 · الفاظ کے پیچھے کا مطلب","অধ্যায় ৭ · ভিন্ন সংস্কৃতি, নতুন উপলব্ধি":"باب 7 · مختلف ثقافت، نئی سمجھ"},"form_guide.label":{"সম্ভাব্য রূপ":"ممکنہ صورت","い-বিশেষণ":"い-صفت","な-বিশেষণ":"な-صفت","ইচ্ছার রূপ":"خواہش کی صورت"},"form_guide.meaning_bn":{"বর্তমান বা ভবিষ্যতের সাধারণ নেতিবাচক রূপ।":"حال یا مستقبل کی عام منفی صورت۔","ます・です ছাড়া সাধারণ রূপ: বর্তমান, অতীত, ইতিবাচক ও নেতিবাচক। N ও な-বিশেষণের だ কখন বাদ/な/の হবে তা প্রতিটি নিয়মে দেওয়া আছে।":"ます・です کے بغیر عام صورت: حال، ماضی، مثبت اور منفی۔ N اور な-صفت کا だ کب حذف/な/の ہوگا یہ ہر اصول میں دیا ہے۔","বিশেষ্যকে বর্ণনা করলে な লাগে। সব গঠনে な থাকবে না; পাঠের সংযোগ দেখুন।":"اسم کی وضاحت کریں تو な لگتا ہے۔ تمام ساختوں میں な نہیں رہے گا؛ سبق کا جوڑ دیکھیں۔","সাধারণ অতীত রূপ।":"عام ماضی صورت۔","ます-রূপ থেকে শুধু ます বাদ দিন।":"ます-صورت سے صرف ます ہٹائیں۔","“করি/করব” ধরনের volitional form।":"\"کروں/کروں گا\" قسم کی volitional form۔","ক্রিয়ার সংযোগের て-form; কোথাও で হয়।":"فعل کے جوڑ کی て-form؛ کہیں で ہوتا ہے۔","কোনো কাজ করতে পারা বোঝায়।":"کوئی کام کر سکنا ظاہر کرتا ہے۔","বিশেষ্য: ব্যক্তি, বস্তু বা বিষয়ের নাম।":"اسم: شخص، چیز یا موضوع کا نام۔","い-বিশেষণ, যেমন বড়, দামি। নেতিবাচক ও অতীতে রূপ বদলায়।":"い-صفت، جیسے بڑا، مہنگا۔ منفی اور ماضی میں صورت بدلتی ہے۔","ক্রিয়ার dictionary form; এর মানে সব ক্রিয়া る দিয়ে শেষ হবে না।":"فعل کی dictionary form؛ اس کا مطلب تمام فعل る سے ختم نہیں ہوں گے۔","শর্তের ば-form।":"شرط کی ば-form۔"},"lessons.examples.bangla":{"সংস্কৃতি আলাদা বলেই আলোচনা করা জরুরি।":"ثقافت الگ کہنے سے ہی بحث کرنا ضروری۔","তিনি শিক্ষক বলার চেয়ে বরং বন্ধুর মতো।":"وہ استاد کہنے سے بلکہ دوست جیسا۔","আগামীকাল হলে সাহায্য করা একেবারে অসম্ভব নয়।":"کل ہو تو مدد کرنا بالکل ناممکن نہیں۔","বয়স বাড়ার সঙ্গে চিন্তার ধরনও বদলায়।":"عمر بڑھنے کے ساتھ سوچ کا انداز بھی بدلتا ہے۔","শিশুটি কাঁদল মনে হতেই সঙ্গে সঙ্গে হাসল।":"بچہ رویا لگتے ہی ساتھ ساتھ ہنسا۔","বিস্তৃত এলাকাজুড়ে জরিপ প্রয়োজন।":"وسیع علاقے بھر میں سروے ضروری۔","খাবারটি যে খেতে পারি না তা নয়, তবে একটু ঝাল।":"کھانا کھا نہیں سکتا ایسا نہیں، لیکن تھوڑا تیکھا۔","গত বছরের তুলনায় ব্যবহারকারী বেড়েছে।":"پچھلے سال کے مقابلے میں استعمال کنندہ بڑھے۔","বসন্ত হলেও সকালে এখনো ঠান্ডা।":"بہار ہو بھی تو صبح ابھی ٹھنڈ۔","যান বা না যান, জানাবেন।":"جائیں یا نہ جائیں، بتائیں گے۔","এভাবে চললে দুর্ঘটনার আশঙ্কা আছে।":"اس طرح چلے تو حادثے کا خدشہ ہے۔","বাইরে বের হওয়া মাত্রই বৃষ্টি শুরু হলো।":"باہر نکلتے ہی بارش شروع ہوئی۔","বন্ধুর সঙ্গে দেখা হওয়ার সূত্রে আমার চিন্তা বদলেছে।":"دوست سے ملاقات ہونے کے سلسلے سے میری سوچ بدلی۔","না করলেও ভদ্রভাবে জানানো ভালো।":"نہ کریں بھی تو شائستگی سے بتانا اچھا۔","টোকিওর তুলনায় এই শহরে ভাড়া কম।":"ٹوکیو کے مقابلے میں اس شہر میں کرایہ کم۔","এইমাত্র বেরিয়েছে, তাই ইতিমধ্যে পৌঁছে যাওয়ার কথা নয়।":"ابھی نکلا ہے، اس لیے پہلے ہی پہنچ جانے کی بات نہیں۔","বিষয়বস্তু যাচাই করার পরে স্বাক্ষর করুন।":"مواد جانچنے کے بعد دستخط کریں۔","জাপানিতে অভ্যস্ত হওয়ার সঙ্গে কথা বলা আনন্দদায়ক হয়েছে।":"جاپانی کا عادی ہونے کے ساتھ بات کرنا خوشگوار ہوا۔","কথা দিয়েছি বলে এখন আর না করা চলে না।":"وعدہ دیا کہہ کر اب اور نہ کرنا نہیں چلتا۔","এই প্রস্তাব সম্পর্কে আমার প্রশ্ন আছে।":"اس تجویز کے بارے میں میرا سوال ہے۔","মতবিনিময় অনুষ্ঠানকে উপলক্ষ করে স্থানীয় কাজে যুক্ত হয়েছি।":"رائے تبادلہ پروگرام کو موقع بنا کر مقامی کام میں جڑا۔","ট্রেন বন্ধ হওয়ায় ট্যাক্সি নেওয়া ছাড়া উপায় ছিল না।":"ٹرین بند ہونے سے ٹیکسی لینے کے سوا چارہ نہیں تھا۔","তিনি হাল না ছেড়ে অনুশীলন চালিয়েছেন।":"انہوں نے ہمت نہ چھوڑ کر مشق جاری رکھی۔","মনে হচ্ছিল যেন স্বপ্ন দেখছি।":"لگ رہا تھا جیسے خواب دیکھ رہا ہوں۔","অতিথির চাহিদা অনুযায়ী কক্ষের ব্যবস্থা করব।":"مہمان کی طلب کے مطابق کمرے کا انتظام کروں گا۔","প্রিয় বন্ধু বলেই সৎভাবে জানাতে চাই।":"پیارا دوست کہنے سے ہی ایمانداری سے بتانا چاہتا ہوں۔","প্রতিদিন অনুশীলন করছে, নিশ্চয়ই দক্ষ হবে বলে মনে করি।":"روزانہ مشق کر رہا ہے، یقیناً ماہر ہوگا سمجھتا ہوں۔","ব্যাখ্যা পড়েছি ঠিকই, কিন্তু ব্যবহারের পদ্ধতি এখনো বুঝিনি।":"وضاحت پڑھی ٹھیک ہی، لیکن استعمال کا طریقہ ابھی نہیں سمجھا۔","দোকানটি সারা বছর খোলা থাকে।":"دکان سارا سال کھلی رہتی ہے۔","এত সহজ উপায়ে সব মনে রাখা যাবে, এমন নয় মোটেও।":"اتنے آسان طریقے سے سب یاد رکھا جا سکے گا، ایسا بالکل نہیں۔","শুধু বিদেশি শিক্ষার্থী নয়, এলাকার মানুষও অংশ নিতে পারেন।":"صرف غیر ملکی طلبہ نہیں، علاقے کے لوگ بھی حصہ لے سکتے ہیں۔","আমার জানা মতে দোকানটি রবিবারও খোলা থাকে।":"میرے جاننے کے مطابق دکان اتوار بھی کھلی رہتی ہے۔","ব্যবস্থার পরিবর্তনের সঙ্গে প্রক্রিয়াও বদলেছে।":"نظام کی تبدیلی کے ساتھ عمل بھی بدلا۔","টাইফুনের কারণে ট্রেন বন্ধ হওয়ার আশঙ্কা আছে।":"طوفان کی وجہ سے ٹرین بند ہونے کا خدشہ ہے۔","তিনি পথঘাট ভালো জানেন, নিশ্চয়ই স্থানীয় বলে মনে হয়।":"وہ راستے اچھی طرح جانتے ہیں، یقیناً مقامی ہیں لگتا ہے۔","জ্বর আছে বলে বিশ্রাম না নিয়ে থাকা চলে না।":"بخار ہے کہہ کر آرام نہ لے کر رہنا نہیں چلتا۔","মতবিনিময় অনুষ্ঠানের মাধ্যমে নতুন বন্ধু হয়েছে।":"رائے تبادلہ پروگرام کے ذریعے نیا دوست ہوا۔","সুস্থ থাকা পর্যন্ত কাজ চালিয়ে যেতে চাই।":"صحت مند رہنے تک کام جاری رکھنا چاہتا ہوں۔","সফল হব কি না তা প্রস্তুতির ওপর নির্ভর করে।":"کامیاب ہوں گا یا نہیں یہ تیاری پر انحصار کرتا ہے۔","আকাশ অন্ধকার হলো মনে হতেই প্রবল বৃষ্টি নামল।":"آسمان اندھیرا ہوا لگتے ہی شدید بارش اتری۔","বড় ভাই সকালে স্বচ্ছন্দ, এর বিপরীতে ছোট ভাই রাতে স্বচ্ছন্দ।":"بڑا بھائی صبح آرام دہ، اس کے برعکس چھوٹا بھائی رات کو آرام دہ۔","ছোটবেলায় নদীতে প্রায়ই খেলতাম।":"بچپن میں دریا میں اکثر کھیلتا تھا۔","এটি বাস্তব অভিজ্ঞতার ভিত্তিতে লেখা প্রতিবেদন।":"یہ حقیقی تجربے کی بنیاد پر لکھی رپورٹ۔","বিদেশের জীবন আনন্দের, আবার পরিবারের জন্য মনও খারাপ হয়।":"بیرون ملک کی زندگی خوشی کی، پھر خاندان کے لیے دل بھی خراب ہوتا ہے۔","অংশ নিন বা না নিন, উত্তর দিন।":"حصہ لیں یا نہ لیں، جواب دیں۔","এই সমস্যা শুধু জাপানে নয়, অন্য দেশেও আছে।":"یہ مسئلہ صرف جاپان میں نہیں، دوسرے ملکوں میں بھی ہے۔","কক্ষটি শান্ত বলার চেয়ে বরং নির্জন লাগে।":"کمرہ پرسکون کہنے سے بلکہ ویران لگتا ہے۔","তিন দিনজুড়ে প্রশিক্ষণ অনুষ্ঠিত হয়েছে।":"تین دن بھر تربیت منعقد ہوئی۔","শহর একদিকে সুবিধাজনক, অন্যদিকে জীবনযাত্রার খরচ বেশি।":"شہر ایک طرف سہولت والا، دوسری طرف زندگی کے اخراجات زیادہ۔","কারণ না জেনে বিচার করা উচিত নয়।":"وجہ نہ جان کر فیصلہ نہیں کرنا چاہیے۔","জাপানি হলেও সবাই যে কানজিতে দক্ষ তা নয়।":"جاپانی ہو بھی تو سب کانجی میں ماہر ہیں ایسا نہیں۔","গ্রাহকসেবার ক্ষেত্রে অন্যের কথা শোনা জরুরি।":"گاہک خدمت کے معاملے میں دوسرے کی بات سننا ضروری۔","জাপানি বলতে পারলেও সম্মানসূচক ভাষায় আত্মবিশ্বাস নেই।":"جاپانی بول سکوں بھی تو تعظیمی زبان میں خود اعتمادی نہیں۔","কণ্ঠস্বর শোনা মাত্রই স্বস্তি পেলাম।":"آواز سنتے ہی راحت پائی۔","অভিজ্ঞতার সঙ্গে মানানসই কাজের দায়িত্ব দেব।":"تجربے کے موزوں کام کی ذمہ داری دوں گا۔","আগে বন্ধুদের সঙ্গে প্রায়ই দীর্ঘ চিঠি লিখতাম।":"پہلے دوستوں کے ساتھ اکثر طویل خط لکھتا تھا۔","সুবিধা বেড়েছে ঠিকই, তবু সমস্যা রয়ে গেছে।":"سہولت بڑھی ٹھیک ہی، پھر بھی مسئلہ رہ گیا۔","জরিপের ফলকে ভিত্তি করে পরিকল্পনা করেছি।":"سروے کے نتیجے کو بنیاد بنا کر منصوبہ بنایا۔","চালিয়ে যেতে পেরেছি ঠিক সহকর্মীরা পাশে ছিলেন বলেই।":"جاری رکھ سکا ٹھیک ساتھی ساتھ تھے کہنے سے ہی۔","তিনি এমনভাবে কথা বললেন যেন কিছুই জানেন না।":"انہوں نے اس طرح بات کی جیسے کچھ جانتے ہی نہیں۔","বন্ধুর জন্য চিন্তায় যোগাযোগ না করে থাকতে পারিনি।":"دوست کے لیے فکر میں رابطہ نہ کرکے رہ نہیں سکا۔","দামি জিনিস সবসময় ভালো হবে এমন নয়।":"مہنگی چیز ہمیشہ اچھی ہوگی ایسا نہیں۔","সহযোগিতা হলো একই লক্ষ্যে একসঙ্গে কাজ করা।":"تعاون ہے ایک ہی ہدف میں ایک ساتھ کام کرنا۔","প্রবল বৃষ্টিতে পরিকল্পনা বদলানো ছাড়া উপায় নেই।":"شدید بارش میں منصوبہ بدلنے کے سوا چارہ نہیں۔","সূচি ঠিক হওয়া মাত্র জানাব।":"شیڈول طے ہوتے ہی بتاؤں گا۔","বয়স নির্বিশেষে যে কেউ অংশ নিতে পারেন।":"عمر سے قطع نظر کوئی بھی حصہ لے سکتا ہے۔","কেইগো বলতে অন্যের প্রতি সম্মান প্রকাশের ভাষা বোঝায়।":"けいご کہنے سے دوسرے کے تئیں احترام ظاہر کرنے والی زبان سمجھی جاتی ہے۔","জনসংখ্যা বৃদ্ধির সঙ্গে আবাসনের প্রয়োজন বেড়েছে।":"آبادی کے اضافے کے ساتھ رہائش کی ضرورت بڑھی۔","আমি শুধু মতামত জানিয়েছি।":"میں نے صرف رائے بتائی۔","এবারের সাফল্য আপনাদের পরিশ্রমের ফলই।":"اس بار کی کامیابی آپ کی محنت کا پھل ہی۔","ঘটনাটি শুনলে না হেসে থাকতে পারি না।":"واقعہ سنیں تو نہ ہنس کر رہ نہیں سکتا۔","এটি কেবল একটি উদাহরণ।":"یہ صرف ایک مثال۔"},"lessons.explanation_bn":{"বক্তার দেখা দুটি ঘটনা খুব দ্রুত বদলে যায়। প্রথম অবস্থা বুঝে ওঠার আগেই পরের অবস্থা আসে—এই পরিবর্তনকে তুলে ধরে।":"بولنے والے کے دیکھے دو واقعات بہت تیزی سے بدل جاتے ہیں۔ پہلی حالت سمجھ اٹھنے سے پہلے ہی اگلی حالت آتی ہے—اس تبدیلی کو سامنے لاتا ہے۔","একটি ঘটনা বড় পরিবর্তন, নতুন অভ্যাস বা সম্পর্কের সূচনা করে। শুধু যেকোনো কারণ নয়, শুরু হওয়ার উপলক্ষকে জোর দেয়।":"ایک واقعہ بڑی تبدیلی، نئی عادت یا تعلق کا آغاز کرتا ہے۔ صرف کوئی بھی وجہ نہیں، شروع ہونے کے موقع پر زور دیتا ہے۔","কাজটি করতে সক্ষম হলেও দায়িত্ব, প্রতিশ্রুতি বা সামাজিক কারণে তা করা গ্রহণযোগ্য নয়। নেতিবাচক ক্রিয়ার সঙ্গে “না করে থাকা চলে না”, অর্থাৎ করতেই হবে।":"کام کرنے کے قابل ہو بھی تو ذمہ داری، وعدے یا سماجی وجہ سے وہ کرنا قابل قبول نہیں۔ منفی فعل کے ساتھ \"نہ کرکے رہنا نہیں چلتا\"، یعنی کرنا ہی ہوگا۔","কোনো শব্দ বা ধারণাকে সামনে এনে তার অর্থ, সংজ্ঞা বা মূল বৈশিষ্ট্য ব্যাখ্যা করুন। প্রবন্ধ ও ব্যাখ্যামূলক লেখায় মানায়।":"کسی لفظ یا تصور کو سامنے لا کر اس کا مطلب، تعریف یا اصل خصوصیت وضاحت کریں۔ مضمون اور وضاحتی تحریر میں موزوں۔","পরিমাণ, ভূমিকা বা গুরুত্বকে সীমিত করে বোঝায়। বক্তা মনে করেন বিষয়টিকে তার চেয়ে বড় করে দেখা ঠিক নয়।":"مقدار، کردار یا اہمیت کو محدود کرکے ظاہر کرتا ہے۔ بولنے والا سمجھتا ہے موضوع کو اس سے بڑا کرکے دیکھنا ٹھیک نہیں۔","Vた-এর সঙ্গে প্রথম কাজ ভালোভাবে করে তারপর সিদ্ধান্ত বা কাজ করুন। Vる-এর সঙ্গে কোনো কাজের ক্ষেত্রে কী গুরুত্বপূর্ণ তা ব্যাখ্যা করুন।":"Vた کے ساتھ پہلا کام اچھی طرح کرکے پھر فیصلہ یا کام کریں۔ Vる کے ساتھ کسی کام کے معاملے میں کیا اہم ہے یہ وضاحت کریں۔","বাস্তবে ঠিক সেই অবস্থা না হলেও তেমন দেখায় বা অনুভূত হয়। কল্পনা ও উপমা তৈরি করতে ব্যবহার করুন।":"حقیقت میں ٹھیک وہ حالت نہ ہو بھی تو ویسا دکھائی دیتا یا محسوس ہوتا ہے۔ تصور اور تشبیہ بنانے کے لیے استعمال کریں۔","পরিচয় বা আসল কারণকে জোর দিয়ে নির্দিষ্ট করে। বক্তা দৃঢ়ভাবে বলেন, এটিই আসল ব্যাখ্যা। আনুষ্ঠানিক যুক্তি বা মূল্যায়নে উপযোগী।":"تعارف یا اصل وجہ پر زور دے کر متعین کرتا ہے۔ بولنے والا پختگی سے کہتا ہے، یہی اصل وضاحت۔ رسمی دلیل یا قدر میں موزوں۔","চাহিদা, ক্ষমতা, পরিস্থিতি বা পরিবর্তনের সঙ্গে সামঞ্জস্য রেখে কাজ বা ব্যবস্থা বদলায়। সবার জন্য একই ব্যবস্থা বোঝায় না।":"طلب، صلاحیت، صورتحال یا تبدیلی کے ساتھ مطابقت رکھ کر کام یا نظام بدلتا ہے۔ سب کے لیے ایک ہی نظام ظاہر نہیں کرتا۔","একই বিষয় বা পরিস্থিতির দুটি ভিন্ন দিক পাশাপাশি তুলে ধরে। ভালো-মন্দ, সুবিধা-অসুবিধা বা পরস্পর ভিন্ন প্রবণতা তুলনা করা যায়।":"ایک ہی موضوع یا صورتحال کے دو مختلف پہلو ساتھ ساتھ سامنے لاتا ہے۔ اچھا-برا، سہولت-پریشانی یا باہمی مختلف رجحان کا موازنہ کیا جا سکتا ہے۔","একটি বড় পরিবর্তন বা ঘটনার সঙ্গে সম্পর্কিত আরেকটি পরিবর্তন ঘটে। সামাজিক প্রবণতা, নীতি ও সংখ্যা ব্যাখ্যায় উপযোগী।":"ایک بڑی تبدیلی یا واقعے کے ساتھ متعلق ایک اور تبدیلی ہوتی ہے۔ سماجی رجحان، پالیسی اور اعداد کی وضاحت میں موزوں۔","আগের অবস্থা বা শর্ত বজায় থাকা পর্যন্ত পরের কথা সত্য। 知[し]っている限[かぎ]り বলতে নিজের জানার সীমার মধ্যেও বোঝায়।":"جب تک پچھلی حالت یا شرط برقرار رہے، بعد والی بات درست رہتی ہے۔ 知[し]っている限[かぎ]り سے اپنی معلومات کی حد کے اندر ہونا بھی مراد ہوتا ہے۔","কারণ বা পরিস্থিতি বিবেচনা করে বক্তা প্রবলভাবে সম্ভাবনা অস্বীকার করেন। এটি বক্তার দৃঢ় বিচার; বৈজ্ঞানিক নিশ্চয়তা দাবি নয়।":"وجہ یا صورتحال کو مدنظر رکھ کر بولنے والا شدت سے امکان رد کرتا ہے۔ یہ بولنے والے کا پختہ فیصلہ؛ سائنسی یقین کا دعویٰ نہیں۔","নিয়ম, তথ্য, গবেষণা বা অভিজ্ঞতাকে সিদ্ধান্তের ভিত্তি হিসেবে ব্যবহার করা হয়। অনুমানের বদলে কী ভিত্তির ওপর কাজ হয়েছে তা বলুন।":"اصول، معلومات، تحقیق یا تجربے کو فیصلے کی بنیاد کے طور پر استعمال کیا جاتا ہے۔ اندازے کے بدلے کس بنیاد پر کام ہوا یہ کہیں۔","কাজ বা অবস্থা দীর্ঘ সময়, বিস্তৃত এলাকা বা বহু বিষয়ের পরিসরজুড়ে চলেছে বোঝায়। পরিসরের বিস্তারকে গুরুত্ব দেয়।":"کام یا حالت طویل وقت، وسیع علاقے یا کئی موضوعات کے دائرے بھر میں چلی ہے ظاہر کرتا ہے۔ دائرے کی وسعت کو اہمیت دیتا ہے۔","অন্য বিকল্প না থাকায় অনিচ্ছা সত্ত্বেও কাজটি করতে হয়। বাইরের পরিস্থিতি বা বাস্তব সীমাবদ্ধতা বক্তাকে বাধ্য করে।":"دوسرا متبادل نہ ہونے سے نا چاہتے ہوئے بھی کام کرنا پڑتا ہے۔ باہر کی صورتحال یا حقیقی حد بولنے والے کو مجبور کرتی ہے۔","আবেগ বা প্রবল স্বাভাবিক তাড়নায় কাজটি না করে থাকা যায় না। নিজের অনুভূতি বা সহজে বোঝা প্রতিক্রিয়া প্রকাশে মানায়।":"جذبے یا شدید فطری تحریک میں کام نہ کرکے رہا نہیں جاتا۔ اپنے احساس یا آسانی سے سمجھے ردعمل کے اظہار میں موزوں۔","একটি শ্রেণির বাইরে একই কথা আরও বিস্তৃত শ্রেণিতেও প্রযোজ্য হলে ব্যবহার করুন। পরে も বা 広[ひろ]く-এর মতো বিস্তারের ইঙ্গিত থাকতে পারে।":"اسے اس وقت استعمال کریں جب ایک زمرے سے باہر وہی بات اس سے وسیع تر زمرے پر بھی لاگو ہو۔ بعد میں も یا 広[ひろ]く جیسے وسعت کے اشارے بھی آ سکتے ہیں۔","আগের তথ্য স্বীকার করেও সীমাবদ্ধতা, ব্যতিক্রম বা সতর্কতা জানান। প্রথম কথাটি মিথ্যা না বলে তাকে শর্তসাপেক্ষ করেন।":"پچھلی معلومات تسلیم کرکے بھی حد، استثنا یا احتیاط بتائیں۔ پہلی بات کو جھوٹ نہ کہہ کر اسے مشروط کرتے ہیں۔","আগের কাজ ঘটার সঙ্গে সঙ্গেই অপ্রত্যাশিত পরিবর্তন বা ঘটনা ঘটে। পরের অংশে সাধারণত পরিকল্পিত নির্দেশ বা ইচ্ছা থাকে না।":"پچھلا کام ہونے کے ساتھ ساتھ ہی غیر متوقع تبدیلی یا واقعہ ہوتا ہے۔ اگلے حصے میں عام طور پر منصوبہ بند ہدایت یا خواہش نہیں ہوتی۔","লক্ষণ, পরিস্থিতি বা জানা তথ্য থেকে বক্তা শক্ত অনুমান করেন। সরাসরি দেখা প্রমাণিত ঘটনা বলার বদলে নিজের বিচার প্রকাশ পায়।":"علامت، صورتحال یا جانی معلومات سے بولنے والا مضبوط اندازہ لگاتا ہے۔ براہ راست دیکھا ثابت شدہ واقعہ کہنے کے بدلے اپنا فیصلہ ظاہر ہوتا ہے۔","ক্রিয়ার ます বাদ দেওয়া রূপে কোনো কাজ শেষ হলে দ্রুত পরের কাজ করার পরিকল্পনা জানায়। বিশেষ্যের সঙ্গে ফল নির্ভর করার অর্থ হয়।":"فعل کے ます حذف شدہ صورت میں کوئی کام ختم ہو تو تیزی سے اگلا کام کرنے کا منصوبہ بتاتا ہے۔ اسم کے ساتھ نتیجہ انحصار کرنے کا مطلب ہوتا ہے۔","একটি পরিস্থিতি সত্য ধরে নিয়েও পরের মতামত বা সীমা বলুন। জোড়ায় AにしてもBにしても হলে উভয় ক্ষেত্রেই একই কথা প্রযোজ্য।":"ایک صورتحال سچ مان کر بھی اگلی رائے یا حد کہیں۔ جوڑے میں AにしてもBにしても ہو تو دونوں صورتوں میں وہی بات لاگو۔","প্রথম বর্ণনাটি পুরো ঠিক নয় মনে করে তার চেয়ে মানানসই দ্বিতীয় বর্ণনা দিন। বিরোধিতা নয়, আরও যথাযথ ভাষায় সংশোধন।":"پہلی وضاحت پوری ٹھیک نہیں سمجھ کر اس سے موزوں دوسری وضاحت دیں۔ مخالفت نہیں، مزید مناسب زبان میں اصلاح۔","একটি কারণকে বিশেষ গুরুত্ব দিয়ে ফলের সঙ্গে জুড়ে দেয়। কারণটি দুর্বল নয়; বক্তা সেটিকেই মূল প্রেরণা হিসেবে সামনে আনছেন।":"ایک وجہ کو خاص اہمیت دے کر نتیجے سے جوڑ دیتا ہے۔ وجہ کمزور نہیں؛ بولنے والا اسی کو اصل تحریک کے طور پر سامنے لا رہا ہے۔","একটি কাজ বা অবস্থা ঘটানো ছাড়া পরের কাজ ঘটে। লিখিত বা আনুষ্ঠানিক ভাষায় Vないで-এর কাছাকাছি অর্থ।":"ایک کام یا حالت واقع کیے بغیر اگلا کام ہوتا ہے۔ تحریری یا رسمی زبان میں Vないで کے قریب مطلب۔","আগের তথ্য সত্য মেনে নিয়ে পরের অংশে তার প্রত্যাশিত ফল না হওয়ার কথা বলুন। লিখিত বা কিছুটা আনুষ্ঠানিক ব্যাখ্যায় বেশি মানায়।":"پچھلی معلومات سچ مان کر اگلے حصے میں اس کا متوقع نتیجہ نہ ہونے کی بات کہیں۔ تحریری یا کچھ رسمی وضاحت میں زیادہ موزوں۔","নেতিবাচক কথাটিকে পুরোপুরি মানতে চান না। সীমিত সক্ষমতা, আংশিক সত্য বা শর্তসাপেক্ষ সম্মতি প্রকাশ করেন।":"منفی بات کو مکمل طور پر ماننا نہیں چاہتے۔ محدود اہلیت، جزوی سچ یا مشروط رضامندی ظاہر کرتے ہیں۔","একটি তুলনার মানদণ্ড নির্দিষ্ট করে পরের তথ্যের পার্থক্য দেখায়। হার, দাম, অতীত ও বর্তমান তুলনায় কাজে আসে।":"ایک موازنے کا معیار متعین کرکے اگلی معلومات کا فرق دکھاتا ہے۔ شرح، قیمت، ماضی اور حال کے موازنے میں کام آتا ہے۔","একটি পরিবর্তন অগ্রসর হওয়ার সঙ্গে অন্য একটি অবস্থাও ধীরে বদলায়। বয়স, সময় বা অভিজ্ঞতার বৃদ্ধি বোঝাতে সুবিধাজনক।":"ایک تبدیلی آگے بڑھنے کے ساتھ ایک اور حالت بھی آہستہ بدلتی ہے۔ عمر، وقت یا تجربے کا اضافہ ظاہر کرنے میں سہولت والا۔","কাজ বা অনুভূতির লক্ষ্য বোঝায়। দুটি পক্ষের বিপরীত বৈশিষ্ট্য তুলনা করতেও ব্যবহার হয়; কোন ব্যবহার তা প্রসঙ্গ দেখে ধরুন।":"کام یا احساس کا ہدف ظاہر کرتا ہے۔ دو فریقوں کی مخالف خصوصیت کا موازنہ کرنے میں بھی استعمال ہوتا ہے؛ کون سا استعمال یہ سیاق دیکھ کر پکڑیں۔","কোনো অভিজ্ঞতা, মাধ্যম বা ব্যক্তির সাহায্যে ফল পাওয়া বোঝায়। সময়ের বিশেষ্যের সঙ্গে পুরো সময়জুড়েও বোঝাতে পারে।":"کسی تجربے، ذریعے یا شخص کی مدد سے نتیجہ پانا ظاہر کرتا ہے۔ وقت کے اسم کے ساتھ پورے وقت بھر میں بھی ظاہر کر سکتا ہے۔","আগের বিষয়টি যাই হোক, পরের ফল বা নিয়ম বদলায় না। বয়স, অভিজ্ঞতা, আবহাওয়া বা অংশগ্রহণের সিদ্ধান্তে ব্যবহার করা যায়।":"پچھلا موضوع جو بھی ہو، اگلا نتیجہ یا اصول نہیں بدلتا۔ عمر، تجربہ، موسم یا شرکت کے فیصلے میں استعمال کیا جا سکتا ہے۔","ভবিষ্যতে অনাকাঙ্ক্ষিত ফলের সম্ভাবনা বোঝায়। সংবাদ, সতর্কতা ও আনুষ্ঠানিক ব্যাখ্যায় ব্যবহার হয়।":"مستقبل میں ناپسندیدہ نتیجے کا امکان ظاہر کرتا ہے۔ خبر، تنبیہ اور رسمی وضاحت میں استعمال ہوتا ہے۔","একটি সাধারণ অনুমান সবার ক্ষেত্রে ঠিক নয়—এই আংশিক নাকচ প্রকাশ করে। কিছু ক্ষেত্রে সত্য হতে পারে, কিন্তু নিশ্চিত নয়।":"ایک عام اندازہ سب کے معاملے میں ٹھیک نہیں—یہ جزوی رد ظاہر کرتا ہے۔ کچھ صورتوں میں سچ ہو سکتا ہے، لیکن یقینی نہیں۔","আগেকার অভ্যাস বা বারবার ঘটত এমন অভিজ্ঞতা স্মরণ করে বলুন। এতে স্মৃতিকাতর ভাব থাকতে পারে।":"پچھلی عادت یا بار بار ہوتا ایسا تجربہ یاد کرکے کہیں۔ اس میں یادوں کا جذبہ ہو سکتا ہے۔"},"lessons.forms":{"必[かなら]ずしも + ইতিবাচক ধারণা + নেতিবাচক predicate":"必[かなら]ずしも + مثبت تصور + منفی predicate","Vない・い-বিশেষণくない + ことはない / N・な-বিশেষণでない + ことはない":"Vない・い-صفتくない + ことはない / N・な-صفتでない + ことはない","Vない-এর ない বাদ + ずにはいられない（する → せずにはいられない）":"Vない کا ない حذف + ずにはいられない（する → せずにはいられない）","Plain form + からこそ（N・な-বিশেষণ: だ + からこそ）":"Plain form + からこそ（N・な-صفت: だ + からこそ）","V・い-বিশেষণ plain + 一方[いっぽう]で / な-বিশেষণ + な一方[いっぽう]で / N + である一方[いっぽう]で":"V・い-صفت plain + 一方[いっぽう]で / な-صفت + な一方[いっぽう]で / N + である一方[いっぽう]で","সময়・এলাকা・পরিসর N + にわたって / N + にわたる + N":"وقت・علاقہ・دائرہ N + にわたって / N + にわたる + N","Vる・Vている・Vない + 限[かぎ]り / N・な-বিশেষণである + 限[かぎ]り":"Vる・Vている・Vない + 限[かぎ]り / N・な-صفتである + 限[かぎ]り","N + とは + সংজ্ঞা・ব্যাখ্যা":"N + とは + تعریف・وضاحت","Plain form + とはいえ（N・な-বিশেষণে だ-ও বাদ যায়）":"Plain form + とはいえ（N・な-صفت میں だ بھی حذف ہوتا ہے）","Vます-stem + 次第[しだい]（সঙ্গে সঙ্গে） / N + 次第[しだい]だ（নির্ভর）":"Vます-stem + 次第[しだい]（فوراً） / N + 次第[しだい]だ（انحصار）","Vない-এর ない বাদ + ざるを得[え]ない（する → せざるを得[え]ない）":"Vない کا ない ہٹا کر + ざるを得[え]ない（する → せざるを得[え]ない）","V・い-বিশেষণ plain + かのようだ / N・な-বিশেষণ + であるかのようだ":"V・い-صفت plain + かのようだ / N・な-صفت + であるかのようだ","V・い-বিশেষণ plain + に違[ちが]いない / N・な-বিশেষণ + に違[ちが]いない":"V・い-صفت plain + に違[ちが]いない / N・な-صفت + に違[ちが]いない","V・い-বিশেষণ plain + ものの / な-বিশেষণ + なものの / N + であるものの":"V・い-صفت plain + ものの / な-صفت + なものの / N + であるものの","Vた + ものだ（অতীতের স্মৃতি）":"Vた + ものだ（ماضی کی یاد）","V・い-বিশেষণ plain + わけがない / な-বিশেষণ + なわけがない / N + のわけがない":"V・い-صفت plain + わけがない / な-صفت + なわけがない / N + のわけがない","Vた + 上[うえ]で（ক্রম） / Vる・Nの + 上[うえ]で（ক্ষেত্র）":"Vた + 上[うえ]で（ترتیب） / Vる・Nの + 上[うえ]で（دائرہ）","N + に対[たい]して / N + に対[たい]する + N（লক্ষ্য）":"N + に対[たい]して / N + に対[たい]する + N（ہدف）"},"lessons.meaning_bn":{"… করা মাত্রই হঠাৎ":"… کرتے ہی اچانک","একদিকে …, অন্যদিকে …":"ایک طرف …، دوسری طرف …","…এর তুলনায়":"…کے مقابلے میں","যদিও …, তবু …":"اگرچہ …، پھر بھی …","…কে সূচনা বা উপলক্ষ করে":"…کو آغاز یا موقع بنا کر","…অনুযায়ী মানিয়ে":"…کے مطابق ڈھال کر","…জুড়ে বিস্তৃতভাবে":"…بھر میں وسیع طور پر","… বলতে কী বোঝায়":"… کہنے سے کیا سمجھا جاتا ہے","… না করেই":"… نہ کرکے ہی","… বলার চেয়ে বরং …":"… کہنے سے بلکہ …","একেবারে … নয়, তা নয় / কিছুটা সম্ভব":"بالکل … نہیں، ایسا نہیں / کچھ ممکن","… নির্বিশেষে":"… سے قطع نظر","…কে ভিত্তি করে":"…کو بنیاد بنا کر","… হলেই সঙ্গে সঙ্গে / …এর ওপর নির্ভর":"… ہو ہی تو ساتھ ساتھ / …پر انحصار","… না করে উপায় নেই":"… نہ کرکے چارہ نہیں","…এর প্রতি / এর বিপরীতে":"…کی طرف / اس کے برعکس","নিশ্চয়ই … হবে, আমার দৃঢ় ধারণা":"یقیناً … ہوگا، میرا پختہ خیال","… হওয়ার কোনো কথাই নয়":"… ہونے کی کوئی بات ہی نہیں","ঠিক … বলেই":"ٹھیک … کہنے سے ہی","… হলো মনে হতেই আবার …":"… ہوا لگتے ہی پھر …","…এর সঙ্গে সংশ্লিষ্ট পরিবর্তনে":"…کے ساتھ متعلق تبدیلی میں","এমন বলা গেলেও":"ایسا کہا جائے بھی تو","… করার পরে / … করার ক্ষেত্রে":"… کرنے کے بعد / … کرنے کے معاملے میں","যতক্ষণ … শর্ত বজায় থাকে":"جب تک … شرط برقرار رہے","একসময় প্রায়ই … করতাম":"ایک وقت اکثر … کرتا تھا","…এর মাধ্যমে / …জুড়ে":"…کے ذریعے / …بھر میں","… হলেও / এমনকি … ক্ষেত্রেও":"… ہو بھی تو / یہاں تک کہ … کے معاملے میں بھی","যত …, তত পরিবর্তন":"جتنا …، اتنی تبدیلی","… না করে থাকতে পারি না":"… نہ کرکے رہ نہیں سکتا","পরিস্থিতিগত কারণে … করা চলে না":"صورتحالی وجہ سے … کرنا نہیں چلتا","অন্য কিছু নয়, ঠিক …ই":"اور کچھ نہیں، ٹھیک …ہی","মাত্র …, এর বেশি নয়":"صرف …، اس سے زیادہ نہیں","শুধু … নয়, অন্যদের ক্ষেত্রেও":"صرف … نہیں، دوسروں کے معاملے میں بھی","খারাপ কিছু ঘটার আশঙ্কা আছে":"برا کچھ ہونے کا خدشہ ہے","সবসময় বা সবার ক্ষেত্রে … নয়":"ہمیشہ یا سب کے معاملے میں … نہیں","মনে হয় যেন …":"لگتا ہے جیسے …"},"lessons.quiz.explanation_bn":{"必[かなら]ずしも + とは限[かぎ]らない সাধারণ অনুমানকে আংশিক নাকচ করে।":"必[かなら]ずしも + とは限[かぎ]らない عام مفروضے کو جزوی طور پر رد کرتا ہے۔","দুটি নেতিবাচক অংশ সীমিত বা শর্তসাপেক্ষ সক্ষমতা প্রকাশ করে।":"دو منفی حصے محدود یا مشروط صلاحیت کو ظاہر کرتے ہیں۔","সংখ্যা কম বা সীমিত হিসেবে দেখাতে にすぎない।":"تعداد کو کم یا محدود دکھانے کے لیے にすぎない۔","する-এর ব্যতিক্রমী ず-রূপ せず।":"する کی غیر معمولی ず صورت せず ہے۔","বিশ্রাম না নিয়ে কাজ চালানোর অর্থে dictionary form + ことなく।":"آرام کیے بغیر کام جاری رکھنے کے معنی میں dictionary form + ことなく۔","ব্যবহারকারী বাড়ার সঙ্গে সম্পর্ক রেখে সেবা বেড়েছে।":"صارفین کے بڑھنے کے ساتھ ساتھ سروس میں بھی اضافہ ہوا ہے۔","ব্যর্থতা থেকে নতুন পড়ার পদ্ধতির শুরু হয়েছে।":"ناکامی سے مطالعے کے نئے طریقے کا آغاز ہوا ہے۔","অভিজ্ঞতা থাকুক বা না থাকুক আবেদন করা যাবে, তাই にかかわらず।":"تجربہ ہو یا نہ ہو، درخواست دی جا سکے گی، اس لیے にかかわらず۔","প্রথমে আলোচনা শেষ করে পরে সিদ্ধান্ত, তাই Vた + 上[うえ]で।":"پہلے بات چیت مکمل کر کے بعد میں فیصلہ، اس لیے Vた + 上[うえ]で۔","নদীর পানি উপচে পড়া অনাকাঙ্ক্ষিত সম্ভাবনা, তাই おそれがある।":"دریا کے پانی کے بہہ نکلنے کا ناپسندیدہ امکان ہے، اس لیے おそれがある۔","স্তরের সঙ্গে মিলিয়ে বই বদলায়, তাই に応[おう]じて।":"سطح کے مطابق کتاب بدلتی ہے، اس لیے に応[おう]じて۔","উপভাষা কী, তার সংজ্ঞা দেওয়া হচ্ছে।":"بولی کیا ہے، اس کی تعریف دی جا رہی ہے۔","বুকিং করার পরও প্রত্যাশিতভাবে যাওয়া হয়নি; ものの এই অমিল দেখায়।":"بکنگ کرنے کے باوجود توقع کے مطابق جانا نہیں ہوا؛ ものの یہی عدم مطابقت دکھاتا ہے۔","ব্যর্থ হওয়াটিকেই প্রস্তুতির গুরুত্ব বোঝার বিশেষ কারণ করা হয়েছে।":"ناکام ہونے کو ہی تیاری کی اہمیت سمجھنے کی خاص وجہ بنایا گیا ہے۔","জানালা খোলার সঙ্গে সঙ্গে অপ্রত্যাশিত বাতাস—Vた + とたん।":"کھڑکی کھولتے ہی غیر متوقع ہوا — Vた + とたん۔","পরিশ্রমের ফলই আসল পরিচয়—এই জোরালো মূল্যায়নে にほかならない।":"محنت کا نتیجہ ہی اصل پہچان ہے — اس پُرزور جائزے کے لیے にほかならない۔","する ব্যতিক্রমীভাবে せざるを得[え]ない হয়।":"する غیر معمولی طور پر せざるを得[え]ない بن جاتا ہے۔","কাজ ছিল সংস্কৃতি শেখার মাধ্যম, তাই を通[とお]して।":"کام ثقافت سیکھنے کا ذریعہ تھا، اس لیے を通[とお]して۔","শিক্ষার্থী ছাড়াও শিক্ষক অংশ নেন; সীমা বিস্তৃত হচ্ছে, তাই に限[かぎ]らず।":"طلبہ کے علاوہ اساتذہ بھی حصہ لیتے ہیں؛ حد وسیع ہو رہی ہے، اس لیے に限[かぎ]らず۔","終[お]わります থেকে ます বাদ দিয়ে 次第[しだい]; কাজ শেষ হলেই পরিকল্পিত যোগাযোগ।":"終[お]わります سے ます ہٹا کر 次第[しだい]; کام ختم ہوتے ہی طے شدہ رابطہ ہوگا۔","সস্তা হওয়া মেনেও কেনার সীমা দেখাচ্ছে।":"سستا ہونے کو ماننے کے باوجود خریدنے کی حد دکھائی جا رہی ہے۔","ব্যাখ্যার ভিত্তি হবে ঘটনা বা তথ্য, তাই に基[もと]づいて।":"وضاحت کی بنیاد واقعہ یا معلومات ہوگی، اس لیے に基[もと]づいて۔","ফিরে আসার পরপরই আবার বের হওয়া—দ্রুত অবস্থা বদলাচ্ছে।":"واپس آتے ہی دوبارہ باہر جانا — صورتحال تیزی سے بدل رہی ہے۔","কথা বলার ধরনকে উপমা দিয়ে বর্ণনা করায় かのように।":"بات کرنے کے انداز کو تشبیہ سے بیان کیا گیا ہے، اس لیے かのように۔","関心[かんしん] বিশেষ্যকে বর্ণনা করছে, তাই に対[たい]する।":"関心[かんしん] اسم کی صفت بیان کر رہا ہے، اس لیے に対[たい]する۔","শান্ত হওয়া ও যাতায়াত অসুবিধা—দুটি ভিন্ন দিক, তাই 一方[いっぽう]で।":"پُرسکون ہونا اور آمد و رفت میں دشواری — دو مختلف پہلو ہیں، اس لیے 一方[いっぽう]で۔","অভিজ্ঞতা বাড়ার সঙ্গে আত্মবিশ্বাস বাড়ছে—পরিবর্তনের সহগতি।":"تجربہ بڑھنے کے ساتھ اعتماد بھی بڑھ رہا ہے — تبدیلی کی ہم آہنگی ہے۔","রাগের বর্ণনা বদলে বিপাকে পড়াকে বেশি যথাযথ বলা হচ্ছে।":"غصے کی وضاحت کے بجائے مشکل میں پڑنے کو زیادہ موزوں کہا جا رہا ہے۔","এখানে বসবাসের শর্ত বজায় থাকাকালীন নিয়ম মানতে হবে।":"یہاں رہائش کی شرط برقرار رہنے کے دوران قواعد کی پابندی کرنی ہوگی۔","ব্যস্ততা মেনেও যোগাযোগের প্রয়োজন বোঝানো হয়েছে।":"مصروفیت کو ماننے کے باوجود رابطے کی ضرورت سمجھائی گئی ہے۔","দুই সপ্তাহজুড়ে সাক্ষাৎকার নেওয়ার বিস্তার বোঝাচ্ছে।":"دو ہفتوں تک انٹرویو لینے کی وسعت کو ظاہر کیا جا رہا ہے۔","আলো জ্বলছে দেখে কেউ আছেন বলে দৃঢ় অনুমান করা হয়েছে।":"روشنی جلتی دیکھ کر کسی کے موجود ہونے کا پختہ اندازہ لگایا گیا ہے۔","এটি দেরি করার সামর্থ্যের প্রশ্ন নয়; গুরুত্বপূর্ণ সভায় দেরি করা চলে না।":"یہ دیر کرنے کی گنجائش کا سوال نہیں ہے؛ اہم اجلاس میں دیر نہیں کی جا سکتی۔","গত মাস হচ্ছে তুলনার ভিত্তিকাল, তাই に比[くら]べて।":"پچھلا مہینہ موازنے کی بنیادی مدت ہے، اس لیے に比[くら]べて۔","অতীতের পুনরাবৃত্ত অভ্যাস স্মরণ করতে Vた + ものだ।":"ماضی کی بار بار کی عادت کو یاد کرنے کے لیے Vた + ものだ۔","কোনোভাবেই বলার কথা নয়—দৃঢ় অস্বীকারে わけがない।":"کسی صورت میں کہنے کی بات نہیں ہے — پختہ انکار کے لیے わけがない۔"},"lessons.quiz.options":{"পড়তে একেবারে পারি না, তা নয়":"ایسا نہیں کہ بالکل پڑھ ہی نہیں سکتا","একেবারেই পড়তে পারি না":"بالکل پڑھ نہیں سکتا","অবশ্যই নিখুঁতভাবে পড়ি":"یقیناً بے عیب طریقے سے پڑھتا ہوں"},"lessons.quiz.prompt":{"দৃঢ় অস্বীকার:「彼[かれ]がそんなことを言[い]う（　）。」":"پختہ انکار:「彼[かれ]がそんなことを言[い]う（　）。」","「読[よ]めないことはない。」—কোন অর্থ?":"「読[よ]めないことはない。」— اس کا کیا مطلب ہے؟","「二週間[にしゅうかん]（　）、社員[しゃいん]に話[はなし]を聞[き]いた。」—সময়ের বিস্তার।":"「二週間[にしゅうかん]（　）、社員[しゃいん]に話[はなし]を聞[き]いた。」— وقت کی وسعت۔","する-এর সঠিক রূপ:「心配[しんぱい]（　）にはいられない。」":"する کی درست صورت:「心配[しんぱい]（　）にはいられない。」","「失敗[しっぱい]（　）、勉強[べんきょう]の方法[ほうほう]を変[か]えた。」—পরিবর্তনের সূচনা।":"「失敗[しっぱい]（　）、勉強[べんきょう]の方法[ほうほう]を変[か]えた。」— تبدیلی کا آغاز۔","「仕事[しごと]（　）、地域[ちいき]の文化[ぶんか]を学[まな]んだ。」—মাধ্যম।":"「仕事[しごと]（　）、地域[ちいき]の文化[ぶんか]を学[まな]んだ。」— ذریعہ۔","「成功[せいこう]は努力[どりょく]の結果[けっか]（　）。」—দৃঢ় মূল্যায়ন।":"「成功[せいこう]は努力[どりょく]の結果[けっか]（　）。」— پختہ جائزہ۔","「先月[せんげつ]（　）、売上[うりあげ]が下[さ]がった。」—তুলনা।":"「先月[せんげつ]（　）、売上[うりあげ]が下[さ]がった。」— موازنہ۔","দৃঢ় অনুমান:「電気[でんき]がついている。誰[だれ]かいる（　）。」":"پختہ اندازہ:「電気[でんき]がついている。誰[だれ]かいる（　）。」","「すべて分[わ]かっている（　）話[はな]す。」—যেন সব জানে।":"「すべて分[わ]かっている（　）話[はな]す。」— جیسے سب کچھ جانتا ہو۔","「大雨[おおあめ]で川[かわ]があふれる（　）。」—অনাকাঙ্ক্ষিত ঝুঁকি।":"「大雨[おおあめ]で川[かわ]があふれる（　）。」— ناپسندیدہ خطرہ۔","「忙[いそが]しい（　）、連絡[れんらく]は必要[ひつよう]だ。」—শর্ত মেনে সীমা।":"「忙[いそが]しい（　）、連絡[れんらく]は必要[ひつよう]だ。」— شرط مان کر حد۔","「環境[かんきょう]問題[もんだい]（　）関心[かんしん]が高[たか]い。」—লক্ষ্যবিষয়।":"「環境[かんきょう]問題[もんだい]（　）関心[かんしん]が高[たか]い。」— ہدف موضوع۔","শেষ হলেই জানাব:「終[お]わり（　）、連絡[れんらく]します。」":"ختم ہوتے ہی بتاؤں گا:「終[お]わり（　）、連絡[れんらく]します。」","「経験[けいけん]が増[ふ]える（　）、自信[じしん]もつく。」—ক্রমে পরিবর্তন।":"「経験[けいけん]が増[ふ]える（　）、自信[じしん]もつく。」— بتدریج تبدیلی۔","「失敗[しっぱい]した（　）、次[つぎ]は準備[じゅんび]を大切[たいせつ]にする。」—কারণে জোর।":"「失敗[しっぱい]した（　）、次[つぎ]は準備[じゅんび]を大切[たいせつ]にする。」— وجہ پر زور۔","「この町[まち]は静[しず]かな（　）、交通[こうつう]が不便[ふべん]です。」—দুটি দিক।":"「この町[まち]は静[しず]かな（　）、交通[こうつう]が不便[ふべん]です。」— دو پہلو۔","「休[やす]む（　）、作業[さぎょう]を続[つづ]けた。」—না করে।":"「休[やす]む（　）、作業[さぎょう]を続[つづ]けた。」— کیے بغیر۔","আগে আলোচনা, তারপর সিদ্ধান্ত:「相談[そうだん]（　）上[うえ]で、決[き]めます。」":"پہلے بات چیت، پھر فیصلہ:「相談[そうだん]（　）上[うえ]で、決[き]めます。」","「学生[がくせい]（　）、先生[せんせい]も参加[さんか]します。」—শিক্ষার্থীর বাইরেও প্রযোজ্য।":"「学生[がくせい]（　）、先生[せんせい]も参加[さんか]します。」— طلبہ سے باہر بھی لاگو۔","「帰[かえ]ってきた（　）、また出[で]かけた。」—দ্রুত পালাবদল।":"「帰[かえ]ってきた（　）、また出[で]かけた。」— تیز تبدیلی۔","する-এর সঠিক রূপ:「中止[ちゅうし]（　）を得[え]ない。」":"する کی درست صورت:「中止[ちゅうし]（　）を得[え]ない。」","「レベル（　）、教材[きょうざい]を変[か]えます。」—মানিয়ে নেওয়া।":"「レベル（　）、教材[きょうざい]を変[か]えます。」— مطابقت اختیار کرنا۔","সংজ্ঞা:「方言[ほうげん]（　）、ある地域[ちいき]で使[つか]われる言葉[ことば]だ。」":"تعریف:「方言[ほうげん]（　）、ある地域[ちいき]で使[つか]われる言葉[ことば]だ。」","「事実[じじつ]（　）、説明[せつめい]してください。」—ভিত্তি।":"「事実[じじつ]（　）、説明[せつめい]してください。」— بنیاد۔","「怒[おこ]っている（　）、困[こま]っているようだ。」—আরও যথাযথ বর্ণনা।":"「怒[おこ]っている（　）、困[こま]っているようだ。」— زیادہ موزوں وضاحت۔","পুরোনো অভ্যাস:「学生時代[がくせいじだい]は、よく図書館[としょかん]へ（　）ものだ。」":"پرانی عادت:「学生時代[がくせいじだい]は、よく図書館[としょかん]へ（　）ものだ。」","「大切[たいせつ]な会議[かいぎ]なので、遅[おく]れる（　）。」—দায়িত্ববোধ।":"「大切[たいせつ]な会議[かいぎ]なので、遅[おく]れる（　）。」— ذمہ داری کا احساس۔","「参加者[さんかしゃ]は十人[じゅうにん]（　）。」—মাত্র দশজন।":"「参加者[さんかしゃ]は十人[じゅうにん]（　）。」— صرف دس افراد۔"},"lessons.tip_bn":{"する-এর রূপ せざる; しざる নয়। নিজের আগ্রহে পছন্দ করা কাজের জন্য নয়।":"する کی صورت せざる؛ しざる نہیں۔ اپنی دلچسپی سے پسند کیے کام کے لیے نہیں۔","わけではない = পুরোপুরি এমন নয়; わけがない = কোনোভাবেই এমন হওয়ার কথা নয়।":"わけではない = مکمل طور پر ایسا نہیں؛ わけがない = کسی طرح بھی ایسا ہونے کی بات نہیں۔","এই পাঠে সংজ্ঞার ব্যবহার; とは思[おも]わなかった-তে বিস্ময়ের ব্যবহার আলাদা।":"اس سبق میں تعریف کا استعمال ہے؛ とは思[おも]わなかった میں حیرت کا استعمال الگ ہے۔","কারণ জানাতে からにほかならない; শুধু বিশেষ্যের পরিচয় জোর দিতে にほかならない।":"وجہ بتانے کے لیے からにほかならない؛ صرف اسم کے تعارف پر زور دینے کے لیے にほかならない۔","অভিজ্ঞতার মাধ্যমে শেখা এবং সারা বছরজুড়ে—এই দুই ব্যবহার প্রসঙ্গ দেখে আলাদা করুন।":"تجربے کے ذریعے سیکھنا اور سارا سال بھر میں—یہ دو استعمال سیاق دیکھ کر الگ کریں۔","যদিও গ্রীষ্ম, তবু পাহাড়ে ঠান্ডা—এই ধরনের স্বীকারের পর সীমা দেখায়।":"اگرچہ گرمی، پھر بھی پہاڑ پر ٹھنڈ—اس قسم کی تسلیم کے بعد حد دکھاتا ہے۔","だけでなく-এর মতো বিস্তার বোঝায়; “এই সময়ের মধ্যে সীমাবদ্ধ” অর্থের に限[かぎ]り আলাদা।":"だけでなく کی طرح وسعت کو ظاہر کرتا ہے؛ “اس وقت کے اندر محدود” کے معنی والا に限[かぎ]り الگ ہے۔","জোরপূর্বক বাইরের বাধ্যবাধকতা নয়; হাসি, চিন্তা, কান্নার মতো ভেতরের তাড়না প্রধান।":"زبردستی باہر کی پابندی نہیں؛ ہنسی، فکر، رونے جیسی اندر کی تحریک اہم۔","に応[おう]じて শর্ত অনুযায়ী বদলায়; にかかわらず শর্তে বদলায় না।":"に応[おう]じて شرط کے مطابق بدلتا ہے؛ にかかわらず شرط سے نہیں بدلتا۔","遅[おく]れるにしても মানে দেরি হলেও; দেরি করার অনুমতি দেওয়া নয়।":"遅[おく]れるにしても کا مطلب ہے چاہے دیر ہو جائے؛ اس کا مطلب دیر کرنے کی اجازت دینا نہیں ہے۔","দুটি ঘটনা শুধু পাশাপাশি নয়; সম্পর্কিত পরিবর্তন দেখাতে হবে।":"دو واقعات صرف ساتھ ساتھ نہیں؛ متعلق تبدیلی دکھانی ہوگی۔","食[た]べられないことはない = খাওয়া একেবারে অসম্ভব নয়; স্বচ্ছন্দে খেতে পারি এমন জোর নেই।":"食[た]べられないことはない = کھانا بالکل ناممکن نہیں ہے؛ آرام سے کھا سکتا ہوں، ایسا زور نہیں ہے۔","নিয়মিত “এর পরে” বলার জন্য てから যথেষ্ট; とたん হঠাৎ ঘটার অনুভূতি দেয়।":"باقاعدہ \"اس کے بعد\" کہنے کے لیے てから کافی؛ とたん اچانک ہونے کا احساس دیتا ہے۔","কিসের সঙ্গে তুলনা করছেন তা পরিষ্কার রাখুন; শুধু সংখ্যা বললেই তুলনা সম্পূর্ণ হয় না।":"کس کے ساتھ موازنہ کر رہے ہیں یہ واضح رکھیں؛ صرف عدد کہنے سے ہی موازنہ مکمل نہیں ہوتا۔","পরের বিশেষ্যকে বর্ণনা করলে かのようなN; ক্রিয়াকে বর্ণনা করলে かのようにV।":"اگلے اسم کی وضاحت کریں تو かのようなN؛ فعل کی وضاحت کریں تو かのようにV۔","রূপ বদলালে অর্থ বদলায়: 確認[かくにん]した上[うえ]で = যাচাইয়ের পরে; 働[はたら]く上[うえ]で = কাজ করার ক্ষেত্রে।":"صورت بدلنے سے معنی بدل جاتا ہے: 確認[かくにん]した上[うえ]で = تصدیق کے بعد؛ 働[はたら]く上[うえ]で = کام کرنے کے معاملے میں۔","মাত্র তিনজন = 三人[さんにん]にすぎない; প্রায় তিনজন = 三人[さんにん]ぐらい—অর্থ আলাদা।":"صرف تین افراد = 三人[さんにん]にすぎない؛ تقریباً تین افراد = 三人[さんにん]ぐらい — معنی الگ ہیں۔","আগের ঘটনাটি পরের পরিবর্তনের শুরু; দৈনন্দিন ছোট কারণেও সবসময় ব্যবহার করবেন না।":"پچھلا واقعہ اگلی تبدیلی کا آغاز؛ روزمرہ چھوٹی وجہ میں بھی ہمیشہ استعمال نہ کریں۔","Vる + 一方[いっぽう]だ শুধু পরিবর্তন এক দিকেই এগোনো বোঝাতে পারে; এই পাঠে শেষে で আছে।":"Vる + 一方[いっぽう]だ صرف تبدیلی کا ایک ہی سمت میں آگے بڑھنا بھی ظاہر کر سکتا ہے؛ اس سبق میں آخر میں で ہے۔","বাক্যের পরের অংশে আগের শর্ত অনুযায়ী মানিয়ে নেওয়ার সম্পর্ক খুঁজুন।":"جملے کے اگلے حصے میں پچھلی شرط کے مطابق ڈھال لینے کا تعلق تلاش کریں۔","から সাধারণ কারণ, からこそ সেই কারণকে জোর দেয়। পরে ইতিবাচক উপদেশ বা মূল্যায়ন প্রায়ই আসে।":"から عام وجہ، からこそ اس وجہ پر زور دیتا ہے۔ بعد میں مثبت مشورہ یا قدر اکثر آتی ہے۔","নিশ্চয়তা অনুভব করলেও এটি অনুমান; হুবহু “প্রমাণিত সত্য” নয়।":"یقین محسوس کریں بھی تو یہ اندازہ؛ بالکل \"ثابت شدہ سچ\" نہیں۔","সাধারণ “ভাবছি” অর্থ নয়। দ্রুত পালাবদল; নিজের ইচ্ছাকৃত ধারাবাহিক কাজ বোঝাতে কম মানায়।":"عام \"سوچ رہا ہوں\" مطلب نہیں۔ تیز تبدیلی؛ اپنے ارادی مسلسل کام کو ظاہر کرنے میں کم موزوں۔","সরাসরি dictionary form লাগে: 休[やす]むことなく; 休[やす]まないことなく লিখবেন না।":"براہ راست dictionary form لگتا ہے: 休[やす]むことなく؛ 休[やす]まないことなく نہ لکھیں۔","এই পাঠে শর্তের ব্যবহার। 時間[じかん]の限[かぎ]り মানে সময়ের শেষ সীমা পর্যন্ত—প্রসঙ্গ আলাদা।":"اس سبق میں شرط کا استعمال ہے۔ 時間[じかん]の限[かぎ]り کا مطلب ہے وقت کی آخری حد تک — سیاق و سباق الگ ہے۔","পরের অংশে পরিবর্তন দিন; একটি নির্দিষ্ট মুহূর্তের সিদ্ধান্ত বা সরাসরি আদেশ মানায় না।":"اگلے حصے میں تبدیلی دیں؛ ایک متعین لمحے کا فیصلہ یا براہ راست حکم موزوں نہیں۔","終[お]わり次第[しだい] = শেষ হলেই; 天気[てんき]次第[しだい] = আবহাওয়ার ওপর নির্ভর।":"終[お]わり次第[しだい] = ختم ہوتے ہی؛ 天気[てんき]次第[しだい] = موسم پر انحصار۔","ভালো ফলের সম্ভাবনায় সাধারণত使[つか]わない; 危険[きけん] বা ক্ষতির পূর্বাভাসে মানায়।":"اچھے نتیجے کے امکان میں عام طور پر使[つか]わない؛ 危険[きけん] یا نقصان کی پیش گوئی میں موزوں ہے۔","একবারের সাম্প্রতিক ঘটনা নয়। ものだ-এর সাধারণ সত্য বা উপদেশের ব্যবহার থেকে এটি আলাদা।":"ایک بار کا حالیہ واقعہ نہیں۔ ものだ کے عام سچ یا نصیحت کے استعمال سے یہ الگ۔","সরাসরি অক্ষমতা できない থেকে আলাদা। 休[やす]まないわけにはいかない মানে বিশ্রাম নিতেই হবে।":"براہ راست نااہلی できない سے الگ ہے۔ 休[やす]まないわけにはいかない کا مطلب ہے آرام کرنا ہی ہوگا۔","একটি নির্দিষ্ট মুহূর্তের জন্য নয়। 一時間[いちじかん]にわたる説明[せつめい] মানে এক ঘণ্টাজুড়ে ব্যাখ্যা।":"کسی ایک مخصوص لمحے کے لیے نہیں ہے۔ 一時間[いちじかん]にわたる説明[せつめい] کا مطلب ہے ایک گھنٹے پر محیط وضاحت۔","দুটি বিকল্পের মধ্যে দ্বিতীয়টি বেশি সঠিক—এই দিকটি খেয়াল রাখুন।":"دو متبادلوں میں دوسرا زیادہ صحیح—اس پہلو کا خیال رکھیں۔","পুরোপুরি অসম্ভব অর্থ নয়। 必[かなら]ずしも-এর সঙ্গে শেষে নেতিবাচক অর্থ রাখুন।":"مکمل طور پر ناممکن کا مطلب نہیں ہے۔ 必[かなら]ずしも کے ساتھ آخر میں منفی معنی رکھیں۔","বিশেষ্যের আগে に対[たい]する: 先生[せんせい]に対[たい]する質問[しつもん]।":"اسم سے پہلے に対[たい]する: 先生[せんせい]に対[たい]する質問[しつもん]۔","単[たん]に “অনুযায়ী” নয়; সিদ্ধান্তের ভিত্তির সঙ্গে দৃঢ় সম্পর্ক আছে।":"単[たん]に “کے مطابق” نہیں ہے؛ فیصلے کی بنیاد کے ساتھ اس کا مضبوط تعلق ہے۔","ものの-এর পরে বাস্তব ফল বা অবস্থা দিন। শুধু দুটি কাজের ক্রম বোঝাতে ব্যবহার করবেন না।":"ものの کے بعد حقیقی نتیجہ یا حالت دیں۔ صرف دو کاموں کی ترتیب ظاہر کرنے کے لیے استعمال نہ کریں۔"},"scope_bn":{"QUARTET II-এর ৭–১২ অধ্যায়ের থিম অনুসরণে নির্বাচিত ৩৬টি গ্রামারের নিজস্ব সহায়ক অনুশীলন। এটি মূল বইয়ের সম্পূর্ণ গ্রামার সূচি নয়।":"QUARTET II کے ابواب 7–12 کے تھیم کی پیروی میں منتخب 36 گرامر کی اپنی معاون مشق۔ یہ اصل کتاب کی مکمل گرامر فہرست نہیں۔"},"study.dialogue":{"ঠিক বলেছেন। এখনই যোগাযোগ করে দেখব।":"ٹھیک کہا۔ ابھی رابطہ کرکے دیکھوں گا۔","হ্যাঁ। যাচাই করার পরে সিদ্ধান্ত নিই।":"ہاں۔ جانچنے کے بعد فیصلہ لیتے ہیں۔","নির্দেশনার কাগজ বাড়ালে কেমন হয়?":"ہدایت کا کاغذ بڑھائیں تو کیسا ہو؟","আজ আপনার বাসায় আসতে পারি?":"آج آپ کے گھر آ سکتا ہوں؟","কিছু হয়েছে?":"کچھ ہوا؟","গ্রাহকসেবার ক্ষেত্রে কোন বিষয়কে গুরুত্ব দেন?":"گاہک خدمت کے معاملے میں کس موضوع کو اہمیت دیتے ہیں؟","আচ্ছা। তাহলে সুবিধামতো একটি দিন জানাবেন?":"اچھا۔ تو سہولت کے مطابق ایک دن بتائیں گے؟","আগামীকাল একটু সাহায্য করবেন?":"کل تھوڑی مدد کریں گے؟","আগে ব্যবহারকারীদের জিজ্ঞেস করে দেখব?":"پہلے استعمال کنندگان سے پوچھ کر دیکھوں؟","এই গ্রাফ থেকে কী বোঝা যায়?":"اس گراف سے کیا سمجھا جاتا ہے؟","রবিবার হলে পারব।":"اتوار ہو تو کر سکوں گا۔","এটিও একটি উপায়, তবে ভাষা বদলানোর প্রয়োজনও আছে বলে মনে করি।":"یہ بھی ایک طریقہ، لیکن زبان بدلنے کی ضرورت بھی ہے سمجھتا ہوں۔","তাহলে রবিবার হলে কেমন হয়?":"تو اتوار ہو تو کیسا ہو؟","প্রথমে গ্রাহকের চাহিদা নিশ্চিত করি।":"پہلے گاہک کی طلب کی تصدیق کرتا ہوں۔","স্টেশনে খোঁজ নিয়ে দেখলে কেমন হয়?":"اسٹیشن پر پوچھ کر دیکھیں تو کیسا ہو؟","কিছু কথা জিজ্ঞেস করতে পারি?":"کچھ بات پوچھ سکتا ہوں؟","একটি গুরুত্বপূর্ণ খাতা হারিয়ে ফেলেছি।":"ایک اہم کاپی کھو دی۔","আগামীকাল কাজ আছে বলে পারব না।":"کل کام ہے کہہ کر نہیں کر سکوں گا۔","দুঃখিত, আজ আমার অন্য কাজ আছে।":"معذرت، آج میرا دوسرا کام ہے۔","অন্য স্কুলেও কি একই রকম হবে?":"دوسرے اسکول میں بھی کیا اسی طرح ہوگا؟","ট্রেন ব্যবহারকারী সবচেয়ে বেশি।":"ٹرین استعمال کنندہ سب سے زیادہ۔","জি, বলুন।":"جی، کہیں۔","শনিবার বিকেল হলে ঠিক আছে।":"ہفتہ سہ پہر ہو تو ٹھیک ہے۔","শুধু এই জরিপ থেকে তা বিচার করা যায় না।":"صرف اس سروے سے اس کا فیصلہ نہیں کیا جا سکتا۔"},"study.kanji":{"বোঝা বা সমাধান":"سمجھنا یا حل","তুলনা":"موازنہ","দৃশ্য":"منظر","প্রত্যাশা":"توقع","বৃদ্ধি":"اضافہ","মিলিত সহযোগিতা":"مشترکہ تعاون","বাহিরে প্রকাশ":"باہر اظہار","অনুভূতি বা অবস্থা":"احساس یا حالت","অতিথি বা ক্রেতা":"مہمان یا خریدار","অভ্যস্ত":"عادی","মনের ভাব":"دل کا جذبہ","ধারণা বা চিন্তা":"تصور یا سوچ","বদলানো":"بدلنا","বিবেচনা":"لحاظ","ভিন্ন":"مختلف","ভরসা":"بھروسا","হ্রাস":"کمی","রূপ বা ছাপ":"صورت یا نقش"},"study.listening_answer":{"এ সপ্তাহে প্রশ্ন তৈরি হবে; আগামী সপ্তাহে লাইব্রেরির প্রবেশপথে জরিপ হবে।":"اس ہفتے سوال تیار ہوں گے؛ اگلے ہفتے لائبریری کے داخلی راستے پر سروے ہوگا۔","জীবনবৃত্তান্ত আনতে হবে; আগামী মঙ্গলবার বেলা ৩টার মধ্যে অফিসে আসতে হবে; পরিবর্তন চাইলে আগের দিনের মধ্যে ফোন করতে হবে।":"سوانح لانا ہوگا؛ اگلے منگل دوپہر 3 بجے تک دفتر آنا ہوگا؛ تبدیلی چاہیں تو پچھلے دن تک فون کرنا ہوگا۔","শনিবার বেলা ২টা; স্টেশনের সামনের লাইব্রেরি; শুক্রবারের মধ্যে জানাতে হবে।":"ہفتہ دوپہر 2 بجے؛ اسٹیشن کے سامنے کی لائبریری؛ جمعہ تک بتانا ہوگا۔","মঙ্গলবার বিকেলে পারবেন; সময়সূচি বদলানো যাবে কি না যাচাই করতে বলছেন।":"منگل سہ پہر کر سکیں گے؛ شیڈول بدلا جا سکے گا یا نہیں جانچنے کو کہہ رہے ہیں۔","সকালে ৬÷১০ = ৬০ শতাংশ; নির্দিষ্ট সময় নেই একজনের। এগুলো অনুশীলনের সংখ্যা।":"صبح 6÷10 = 60 فیصد؛ متعین وقت نہیں ایک کا۔ یہ مشق کے اعداد۔","গতকাল দোকানে যে আসনে বসেছিলেন সেখানে; আজ সন্ধ্যায় নিতে যাবেন।":"کل دکان میں جس نشست پر بیٹھے تھے وہاں؛ آج شام لینے جائیں گے۔"},"study.listening_question":{"ব্যাগ কোথায় পাওয়া গেছে? বক্তা কখন নিতে যাবেন?":"بیگ کہاں ملا؟ بولنے والا کب لینے جائے گا؟","কী আনতে হবে, কখন আসতে হবে, পরিবর্তন চাইলে কী করবেন?":"کیا لانا ہوگا، کب آنا ہوگا، تبدیلی چاہیں تو کیا کریں گے؟","সকালে পড়ার অনুপাত কত? নির্দিষ্ট সময় নেই কতজনের?":"صبح پڑھنے کا تناسب کتنا؟ متعین وقت نہیں کتنے لوگوں کا؟","কখন, কোথায় এবং কত দিনের মধ্যে জানাতে হবে?":"کب، کہاں اور کتنے دنوں کے اندر بتانا ہوگا؟","এ সপ্তাহে কী হবে? জরিপ কোথায় এবং কখন হবে?":"اس ہفتے کیا ہوگا؟ سروے کہاں اور کب ہوگا؟","বক্তা কোন দিন পারবেন? শ্রোতার কাছে কী অনুরোধ করছেন?":"بولنے والا کس دن کر سکے گا؟ سننے والے سے کیا درخواست کر رہے ہیں؟"},"study.questions":{"সবার কাছে একই ব্যাখ্যা যথেষ্ট নয় কেন?":"سب کے نزدیک وہی وضاحت کافی کیوں نہیں؟","মিনা যাওয়ার আগে কী করেনি?":"مینا نے جانے سے پہلے کیا نہیں کیا؟","গ্রাহকের প্রয়োজন অনুযায়ী ব্যাখ্যা মানিয়ে নেওয়া।":"گاہک کی ضرورت کے مطابق وضاحت ڈھال لینا۔","প্রথমবার আসা ব্যক্তির উদাহরণটি কী বোঝায়?":"پہلی بار آنے والے شخص کی مثال کیا ظاہر کرتی ہے؟","দৃষ্টিকোণ বদলানোর কারণ কী ছিল?":"نقطہ نظر بدلنے کی وجہ کیا تھی؟","লেখাটির মূল শিক্ষা কী?":"تحریر کی اصل تعلیم کیا؟","পরের বাক্যে কাজ থাকার কারণ ও রবিবারের বিকল্প দেওয়ার তথ্য থেকে।":"اگلے جملے میں کام ہونے کی وجہ اور اتوار کا متبادل دینے کی معلومات سے۔","ট্রেন ব্যবহারকারীর অনুপাত কত এবং কীভাবে পেলেন?":"ٹرین استعمال کنندہ کا تناسب کتنا اور کیسے پایا؟","প্রথমে কাগজ বাড়াতে চেয়েছিল; পরে ব্যবহারকারীর প্রয়োজন বুঝে ভাষা সহজ করেছে।":"پہلے کاغذ بڑھانا چاہا تھا؛ بعد میں استعمال کنندہ کی ضرورت سمجھ کر زبان آسان کی۔","খাতা পাওয়া গেছে বলে স্টেশনের খবর আসার পর।":"کاپی مل گئی کہہ کر اسٹیشن کی خبر آنے کے بعد۔","না; আগামীকাল পারবে না, রবিবার পারবে বলে বিকল্প দিয়েছে।":"نہیں؛ کل نہیں کر سکے گا، اتوار کر سکے گا کہہ کر متبادل دیا۔","ব্যবহারকারীদের সঙ্গে কথা বলে সমস্যাটি শ্রেণিবিভাগের নাম বুঝতে অসুবিধা বলে জানা যায়।":"استعمال کنندگان سے بات کرکے مسئلہ درجہ بندی کا نام سمجھنے میں دشواری ہے معلوم ہوتا ہے۔","আমন্ত্রণের ভাষা শুনে সময় ধরে না নিয়ে পরিস্থিতি যাচাই ও আলোচনা করা দরকার।":"دعوت کی زبان سن کر وقت پکڑ نہ لے کر صورتحال کی جانچ اور بحث کرنا ضروری۔","১২÷২০×১০০ = ৬০ শতাংশ।":"12÷20×100 = 60 فیصد۔","কোন ঘটনায় ইউয়ের অনুভূতি বদলাল?":"کس واقعے میں یو کا احساس بدلا؟","প্রথম প্রস্তাব ও শেষ পদক্ষেপ কীভাবে আলাদা?":"پہلی تجویز اور آخری قدم کیسے الگ؟","গ্রাহকের অভিজ্ঞতা ও চাহিদা আলাদা; সে অনুযায়ী ক্রম ও ভাষা বদলাতে হয়।":"گاہک کا تجربہ اور طلب الگ؛ اس کے مطابق ترتیب اور زبان بدلنی ہوتی ہے۔","না; খাতা হারিয়ে ইউয়ের অনুভূতির উপমা। かのように সূত্রটি দেখুন।":"نہیں؛ کاپی کھو کر یو کے احساس کی تشبیہ۔ かのように فارمولا دیکھیں۔","কথাগুলো মুছে যাওয়ার বর্ণনাটি কি বাস্তব ঘটনা?":"باتیں مٹ جانے کی وضاحت کیا حقیقی واقعہ؟","বন্ধুর সময় আছে কি না যোগাযোগ করে নিশ্চিত করেনি। দ্বিতীয় ও তৃতীয় বাক্য মিলিয়ে বুঝবেন।":"دوست کے پاس وقت ہے یا نہیں رابطہ کرکے تصدیق نہیں کی۔ دوسرا اور تیسرا جملہ ملا کر سمجھیں گے۔","難[むずか]しい-এর উদ্দেশ্য কোন তথ্য থেকে নিশ্চিত হলেন?":"難[むずか]しい کا مفہوم کس معلومات سے یقینی ہوا؟","এই কথোপকথনে বন্ধু কি সাহায্য একেবারে অস্বীকার করেছে?":"اس گفتگو میں دوست نے کیا مدد بالکل رد کر دی؟","উত্তরদাতা কেবল একটি ক্লাসের ২০ জন; নমুনা জাতীয় প্রতিনিধিত্ব নিশ্চিত করে না।":"جواب دہندگان صرف ایک کلاس کے 20 لوگ؛ نمونہ قومی نمائندگی یقینی نہیں بناتا۔","কেন সারা জাপানের বিষয়ে সিদ্ধান্ত নেওয়া যায় না?":"کیوں پورے جاپان کے بارے میں فیصلہ نہیں لیا جا سکتا؟"},"study.reading":{"たとえば-এর উদাহরণ আগের মানিয়ে নেওয়ার বক্তব্যকে স্পষ্ট করে।":"たとえば کی مثال پچھلے ڈھال لینے کے بیان کو واضح کرتی ہے۔","পরের কারণ ও বিকল্প দিন থেকে আগের কথার উদ্দেশ্য পরিষ্কার হয়।":"اگلی وجہ اور متبادل دن سے پچھلی بات کا مقصد واضح ہوتا ہے۔","অন্য দৃষ্টিকোণ থেকে ভাবাই উন্নতির সূচনা হলো।":"دوسرے نقطہ نظر سے سوچنا ہی بہتری کا آغاز ہوا۔","একটি ছোট দোকানের ম্যানেজারকে জিজ্ঞেস করলাম, কাজের কোন বিষয়টিকে গুরুত্ব দেন।":"ایک چھوٹی دکان کے منیجر سے پوچھا، کام کے کس موضوع کو اہمیت دیتے ہیں۔","কাগজ কম থাকা নয়, নামের অর্থ না বোঝা—সমস্যার ব্যাখ্যা বদলাল।":"کاغذ کم ہونا نہیں، نام کا مطلب نہ سمجھنا—مسئلے کی وضاحت بدلی۔","এই বাক্য গল্পের মোড় বদলায়; আগের উদ্বেগের বিপরীতে ভালো খবর।":"یہ جملہ کہانی کا موڑ بدلتا ہے؛ پچھلی پریشانی کے برعکس اچھی خبر۔","সমাধান হিসেবে আলোচনা এসেছে; কোনো দেশের সব মানুষকে নিয়ে নিয়ম বলা হয়নি।":"حل کے طور پر بحث آئی؛ کسی ملک کے تمام لوگوں کو لے کر اصول نہیں کہا گیا۔","শেষ বাক্য ঘটনাটির সাধারণ শিক্ষা; উদাহরণের বাইরে অতিরিক্ত ফল দাবি করা হয়নি।":"آخری جملہ واقعے کی عام تعلیم؛ مثال کے باہر اضافی نتیجہ دعویٰ نہیں کیا گیا۔","ক্লাসের অনুশীলনের জন্য ধরে নিই, ২০ শিক্ষার্থীকে যাতায়াতের উপায় জিজ্ঞেস করা হলো।":"کلاس کی مشق کے لیے فرض کریں، 20 طلبہ سے آمد و رفت کا ذریعہ پوچھا گیا۔","ম্যানেজার বললেন, “একই ব্যাখ্যা বারবার বলাই যথেষ্ট নয়।”":"منیجر نے کہا، \"وہی وضاحت بار بار کہنا ہی کافی نہیں۔\"","তার মনে হলো, যেন গুরুত্বপূর্ণ কথাগুলোও হারিয়ে গেছে।":"اسے لگا، جیسے اہم باتیں بھی کھو گئیں۔","しかし আগের প্রত্যাশার সঙ্গে বাস্তব অবস্থার অমিল আনে।":"しかし پچھلی توقع کے ساتھ حقیقی حالت کی عدم مطابقت لاتا ہے۔","এই দৃশ্যে কী বোঝায় বলা হয়েছে; সব ক্ষেত্রে একই অর্থ দাবি করা হয়নি।":"اس منظر میں کیا ظاہر کرتا ہے کہا گیا؛ تمام صورتوں میں وہی مطلب دعویٰ نہیں کیا گیا۔","খাতাটি হাতে পেয়ে ইউ না হেসে থাকতে পারল না।":"کاپی ہاتھ میں پا کر یو نہ ہنس کر رہ نہیں سکا۔","পরদিন স্টেশন থেকে জানানো হলো খাতাটি পাওয়া গেছে।":"اگلے دن اسٹیشن سے بتایا گیا کاپی مل گئی۔","দুজন সময়সূচি নিশ্চিত করার গুরুত্ব নিয়ে আলোচনা করল।":"دونوں نے شیڈول کی تصدیق کی اہمیت پر بحث کی۔","কিন্তু বন্ধু তখন কাজে বের হওয়ার ঠিক আগের অবস্থায় ছিল।":"لیکن دوست تب کام پر نکلنے کے ٹھیک پہلے کی حالت میں تھا۔","তারপর বলল, “কাজ আছে, তবে রবিবার হলে সাহায্য করতে পারব।”":"پھر کہا، \"کام ہے، لیکن اتوار ہو تو مدد کر سکوں گا۔\"","এটি অনুশীলনের কাল্পনিক জরিপ; বাস্তব গবেষণা নয়।":"یہ مشق کا فرضی سروے؛ حقیقی تحقیق نہیں۔","বন্ধু বলল, “আগামীকাল একটু কঠিন হবে।”":"دوست نے کہا، \"کل تھوڑا مشکل ہوگا۔\"","প্রথম বাক্যে সমস্যাটি এসেছে; খাতাটির দৈনন্দিন গুরুত্বও জানা গেল।":"پہلے جملے میں مسئلہ آیا؛ کاپی کی روزمرہ اہمیت بھی معلوم ہوئی۔","বাসায় পৌঁছানো মাত্র সে বিষয়টি টের পেল।":"گھر پہنچتے ہی اسے موضوع کا احساس ہوا۔","অনুরোধের বিষয় ও সময় আগে দেওয়া হয়েছে।":"درخواست کا موضوع اور وقت پہلے دیا گیا۔","পরদিন সে কোনো যোগাযোগ না করেই বন্ধুর বাসায় গেল।":"اگلے دن وہ کوئی رابطہ نہ کرکے ہی دوست کے گھر گئی۔","しかし উপসংহারের সীমা নির্দেশ করে।":"しかし اختتام کی حد اشارہ کرتا ہے۔","মোট ১২+৫+৩=২০; গণনার ভিত্তি একই আছে।":"کل 12+5+3=20؛ گنتی کی بنیاد ایک ہی ہے۔","শেষ বাক্য লেখার মূল শিক্ষা।":"آخری جملہ تحریر کی اصل تعلیم۔","最初[さいしょ]は প্রথম প্রস্তাব চিহ্নিত করছে; এটি চূড়ান্ত সমাধান নয়।":"最初[さいしょ]は پہلی تجویز کی نشاندہی کر رہا ہے؛ یہ حتمی حل نہیں ہے۔","প্রথমে নির্দেশনার কাগজ বাড়ানোর কথা ভাবা হলো।":"پہلے ہدایت کا کاغذ بڑھانے کی بات سوچی گئی۔","এই অভিজ্ঞতার মাধ্যমে মিনা কথার পাশাপাশি পরিস্থিতিও যাচাই করতে শুরু করল।":"اس تجربے کے ذریعے مینا بات کے ساتھ ساتھ صورتحال بھی جانچنا شروع کر گئی۔","কারণ লক্ষ্যগোষ্ঠী কেবল একটি ক্লাস।":"وجہ ہدف گروہ صرف ایک کلاس۔","১২ জন ট্রেন, ৫ জন সাইকেল এবং ৩ জন হেঁটে যাওয়ার কথা বলল।":"12 لوگ ٹرین، 5 لوگ سائیکل اور 3 لوگ پیدل جانے کی بات کہی۔","かのように উপমা; বাস্তবে সব কথা মুছে গেছে এমন তথ্য নয়।":"かのように تشبیہ؛ حقیقت میں تمام باتیں مٹ گئیں ایسی معلومات نہیں۔","聞[き]きました-র প্রশ্নবিষয় দিয়ে পরের উত্তরের কেন্দ্র নির্ধারিত হয়।":"聞[き]きました کے سوال کے موضوع سے اگلے جواب کا مرکز طے ہوتا ہے۔","ট্রেন ব্যবহারকারীর অনুপাত ৬০ শতাংশ।":"ٹرین استعمال کنندہ کا تناسب 60 فیصد۔","তাই কর্মীরা পরিচিত ভাষায় লেখা নির্দেশনা ব্যবহার করলেন।":"اس لیے کارکنوں نے واقف زبان میں لکھی ہدایت استعمال کی۔","এখানে 難[むずか]しい কেবল কাজের জটিলতা নাও বোঝাতে পারে।":"یہاں 難[むずか]しい سے صرف کام کی پیچیدگی مراد نہیں بھی ہو سکتی۔","を通[とお]して অভিজ্ঞতার মাধ্যমে শেখা; ようになった আচরণের পরিবর্তন।":"を通[とお]して تجربے کے ذریعے سیکھنا؛ ようになった رویے کی تبدیلی۔","に応[おう]じて মানিয়ে নেওয়া; そうです বক্তার কাছ থেকে শোনা তথ্য।":"に応[おう]じて مطابقت اختیار کرنا؛ そうです بولنے والے کی سنی ہوئی معلومات۔","たとたん পৌঁছানোর সঙ্গে হঠাৎ উপলব্ধি বোঝায়।":"たとたん پہنچنے کے ساتھ اچانک سمجھ ظاہر کرتا ہے۔","গ্রাহকের চাহিদা অনুযায়ী তিনি ব্যাখ্যার ক্রম ও ভাষা বদলান।":"گاہک کی طلب کے مطابق وہ وضاحت کی ترتیب اور زبان بدلتے ہیں۔","ことなく মানে না করে; মিনার আগেই খবর না দেওয়া এখানে গুরুত্বপূর্ণ।":"ことなく مطلب نہ کرکے؛ مینا کا پہلے ہی خبر نہ دینا یہاں اہم۔","কেন এক বন্ধুকে পরদিন বাসা বদলে সাহায্য করতে বলল।":"کیوں ایک دوست کو اگلے دن گھر بدلنے میں مدد کرنے کو کہا۔","শেষ বাক্য প্রতিবেদকের উপলব্ধি; ম্যানেজারের সরাসরি উদ্ধৃতি নয়।":"آخری جملہ رپورٹر کی سمجھ؛ منیجر کا براہ راست اقتباس نہیں۔","মনে হলো, মন দিয়ে অন্যের কথা শোনাই আস্থার শুরু।":"لگا، توجہ سے دوسرے کی بات سننا ہی اعتماد کا آغاز۔","শেষ প্রতিক্রিয়া থেকে স্বস্তি ও আনন্দ বোঝা যায়।":"آخری ردعمل سے راحت اور خوشی سمجھی جاتی ہے۔","প্রথম বাক্যে বলা তথ্যটি আমন্ত্রণের ভাষা; এখনো সময় নির্দিষ্ট হয়নি।":"پہلے جملے میں کہی معلومات دعوت کی زبان؛ ابھی وقت متعین نہیں ہوا۔","কিন্তু ব্যবহারকারীদের সঙ্গে কথা বলে জানা গেল, শ্রেণিবিভাগের নাম বোঝা কঠিন।":"لیکن استعمال کنندگان سے بات کرکے معلوم ہوا، درجہ بندی کا نام سمجھنا مشکل۔","ইউ প্রতিদিন ব্যবহার করা খাতাটি ট্রেনে ফেলে এল।":"یو روزانہ استعمال کرنے والی کاپی ٹرین میں چھوڑ آیا۔","だけでは十分[じゅうぶん]ではない সীমা দেখাচ্ছে; কোনো ব্যাখ্যাই প্রয়োজন নেই বলা হয়নি।":"だけでは十分[じゅうぶん]ではない حد دکھا رہا ہے؛ یہ نہیں کہا گیا کہ کسی وضاحت کی ضرورت ہی نہیں ہے۔","এই পরিস্থিতিতে “কঠিন” কথাটি পরদিনের অনুরোধ প্রত্যাখ্যান করছে।":"اس صورتحال میں \"مشکل\" بات اگلے دن کی درخواست رد کر رہی ہے۔","অর্থ বুঝতে শব্দের পাশাপাশি প্রসঙ্গও জরুরি।":"مطلب سمجھنے کے لیے لفظ کے ساتھ ساتھ سیاق بھی ضروری۔","そこで আগের তথ্যের ভিত্তিতে করা পদক্ষেপকে যুক্ত করছে।":"そこで پچھلی معلومات کی بنیاد پر کیے قدم کو جوڑ رہا ہے۔","মিনাকে এক বন্ধু বলল, “আবার বেড়াতে এসো।”":"مینا کو ایک دوست نے کہا، \"پھر گھومنے آؤ۔\"","にすぎない পরিসরের সীমাবদ্ধতা দেখায়।":"にすぎない دائرے کی حد دکھاتا ہے۔","একটি লাইব্রেরিতে বই খুঁজতে বেশি সময় লাগে বলে মতামত এসেছিল।":"ایک لائبریری میں کتاب تلاش کرنے میں زیادہ وقت لگتا ہے کہہ کر رائے آئی تھی۔","শুরুতে ব্যবহারকারীর সমস্যা তুলে ধরা হয়েছে।":"آغاز میں استعمال کنندہ کا مسئلہ سامنے لایا گیا۔","১২÷২০×১০০=৬০; শুধু সংখ্যা নয়, মোটের ভিত্তি দেখুন।":"12÷20×100=60؛ صرف عدد نہیں، کل کی بنیاد دیکھیں۔","তবে শুধু এই ফল দিয়ে জাপানের সব শিক্ষার্থী সম্পর্কে বলা যায় না।":"لیکن صرف اس نتیجے سے جاپان کے تمام طلبہ کے بارے میں کہا نہیں جا سکتا۔","যেমন, প্রথমবার আসা ব্যক্তিকে ব্যবহারের পদ্ধতি দিয়ে বোঝানো শুরু করেন।":"جیسے، پہلی بار آنے والے شخص کو استعمال کے طریقے سے سمجھانا شروع کرتے ہیں۔"},"study.reading_title":{"“একটু কঠিন” কথাটির পর কী হলো":"“ذرا مشکل” کہنے کے بعد کیا ہوا","সমস্যার বদলে প্রয়োজন থেকে ভাবা":"مسئلے کے بجائے ضرورت سے سوچنا","ভালো সেবা মানে একই উত্তর নয়":"اچھی سروس کا مطلب ایک ہی جواب نہیں ہے","একটি আমন্ত্রণ, দুই রকম ধারণা":"ایک دعوت، دو طرح کے تصورات","হারানো খাতার ছোট গল্প":"گمشدہ کاپی کی چھوٹی کہانی","জরিপের সংখ্যা থেকে কতটুকু বলা যায়":"سروے کے اعداد سے کتنا کہا جا سکتا ہے"},"study.strategy":{"শব্দের আক্ষরিক অর্থের পাশাপাশি কে, কাকে, কোন অনুরোধে বলছে তা দেখুন। পরোক্ষ কথাকে সবার জন্য স্থির নিয়ম হিসেবে ধরবেন না।":"لفظ کے لفظی مطلب کے ساتھ ساتھ کون، کسے، کس درخواست میں کہہ رہا ہے یہ دیکھیں۔ بالواسطہ بات کو سب کے لیے مستقل اصول کے طور پر نہ پکڑیں۔","শিরোনাম ও ছোট উপশিরোনাম দেখে যুক্তির ধাপ ধরুন। দাবি, কারণ, উদাহরণ ও বিকল্পকে আলাদা করুন। মতের বিরোধিতা করলে কারণসহ বিকল্প দিন।":"عنوان اور چھوٹے ذیلی عنوان دیکھ کر دلیل کے مراحل پکڑیں۔ دعویٰ، وجہ، مثال اور متبادل کو الگ کریں۔ رائے کی مخالفت کریں تو وجہ سمیت متبادل دیں۔","চরিত্রের অনুভূতি কোন ঘটনা বা শব্দে বদলেছে তা দেখুন। উপমাকে বাস্তব ঘটনা হিসেবে নেবেন না। পর্যালোচনায় নিজের মূল্যায়নের কারণ দিন।":"کردار کا احساس کس واقعے یا لفظ سے بدلا یہ دیکھیں۔ تشبیہ کو حقیقی واقعے کے طور پر نہ لیں۔ جائزے میں اپنی قدر کی وجہ دیں۔","প্রশ্নের উত্তরে বক্তা প্রথমে সিদ্ধান্ত বলেছেন, না উদাহরণ দিয়েছেন, তা ধরুন। উদাহরণ কোন মূল কথাকে বোঝাচ্ছে সেটি খুঁজুন।":"سوال کے جواب میں بولنے والے نے پہلے فیصلہ کہا، یا مثال دی، یہ پکڑیں۔ مثال کس اصل بات کو ظاہر کر رہی ہے وہ تلاش کریں۔","বাক্যে কর্তা বাদ গেলে আগের বাক্য ও কথোপকথনের প্রবাহ দেখুন। অনুমান আর স্পষ্টভাবে বলা তথ্য আলাদা রাখুন।":"جملے میں فاعل حذف ہو تو پچھلا جملہ اور گفتگو کا بہاؤ دیکھیں۔ اندازہ اور واضح طور پر کہی معلومات الگ رکھیں۔","জরিপের লক্ষ্যগোষ্ঠী, মোট উত্তরদাতা, সময় ও শতাংশের ভিত্তি আগে পড়ুন। উদাহরণের সংখ্যাকে বাস্তব জরিপের ফল হিসেবে ব্যবহার করবেন না।":"سروے کا ہدف گروہ، کل جواب دہندگان، وقت اور فیصد کی بنیاد پہلے پڑھیں۔ مثال کے اعداد کو حقیقی سروے کے نتیجے کے طور پر استعمال نہ کریں۔"},"study.vocab":{"প্রকাশভঙ্গি":"اظہار کا انداز","দৃষ্টিকোণ":"نقطہ نظر","ভুল বোঝাবুঝি":"غلط فہمی","অনুভূতি":"احساسات","আস্থা":"اعتماد","উদ্বেগ":"پریشانی","অভিজ্ঞতা":"تجربہ","লক্ষ্যগোষ্ঠী বা বিষয়":"ہدف گروہ یا موضوع","জরিপ বা অনুসন্ধান":"سروے یا تحقیق","অনুপাত":"تناسب","উদ্দেশ্য":"مقصد","অন্যের কথা বিবেচনা":"دوسرے کی بات کا لحاظ","প্রসঙ্গ":"سیاق","ভূমিকা":"کردار","সংকোচ বা সংযম":"جھجک یا ضبط","চিন্তার সূচনা বা ধারণা":"سوچ کا آغاز یا تصور","পারস্পরিক আদানপ্রদান":"باہمی تبادلہ","কৌশল বা বুদ্ধিদীপ্ত চেষ্টা":"حکمت عملی یا ذہانت بھری کوشش","সহযোগিতা":"تعاون","চাহিদা বা আশা":"طلب یا امید","ভিন্ন সংস্কৃতি":"مختلف ثقافت","প্রস্তাব":"تجویز","অভ্যাস বা রীতি":"عادت یا رسم","স্বস্তি":"راحت","গ্রাহকসেবা":"گاہک خدمت","হ্রাস":"کمی","মনের ওপর ছাপ":"دل پر نقش","বৃদ্ধি":"اضافہ","তুলনা":"موازنہ","গল্প বা আখ্যান":"کہانی یا بیان","দৃশ্য বা পরিস্থিতি":"منظر یا صورتحال","যাচাই করা":"جانچ کرنا","প্রত্যাখ্যান করা":"رد کرنا","উন্নতি":"بہتری","জানানো":"بتانا"},"study.writing":{"আমি খাতা হারানো একজনের ছোট গল্প পড়েছি।":"میں نے کاپی کھونے والے ایک کی چھوٹی کہانی پڑھی۔","ট্রেন ব্যবহারকারী ১২ জন, যা সবচেয়ে বড় অংশ।":"ٹرین استعمال کنندہ 12 لوگ، جو سب سے بڑا حصہ۔","কিন্তু বন্ধু ভেবেছিল এখনো আলোচনা দরকার।":"لیکن دوست نے سوچا تھا ابھی بحث ضروری۔","আমারও প্রিয় জিনিস হারানোর অভিজ্ঞতা আছে বলে অনুভূতিটি বুঝেছি।":"مجھے بھی پیاری چیز کھونے کا تجربہ ہے کہہ کر احساس سمجھا۔","অনুশীলনের জরিপে একটি ক্লাসের ২০ শিক্ষার্থীকে প্রশ্ন করা হয়েছে।":"مشق کے سروے میں ایک کلاس کے 20 طلبہ سے سوال کیا گیا۔","এই অভিজ্ঞতার পর গুরুত্বপূর্ণ বিষয় স্পষ্টভাবে বলে নিশ্চিত করার চেষ্টা করি।":"اس تجربے کے بعد اہم موضوع واضح طور پر کہہ کر تصدیق کرنے کی کوشش کرتا ہوں۔","মূল চরিত্রের উদ্বেগ পরিচিত ভাষায় তুলে ধরা হয়েছে।":"مرکزی کردار کی پریشانی واقف زبان میں سامنے لائی گئی۔","যেমন কঠিন শব্দ পরিচিত প্রকাশে বদলে দেওয়া যায়।":"جیسے مشکل لفظ واقف اظہار میں بدل دیا جا سکتا ہے۔","তাই যারা ব্যবহার করবেন তাঁদের মতামত শোনা উচিত বলে মনে করি।":"اس لیے جو استعمال کریں گے ان کی رائے سننی چاہیے سمجھتا ہوں۔","এটি এমন গল্প যা দৈনন্দিন ছোট ঘটনাকেও গুরুত্ব দিতে শেখায়।":"یہ ایسی کہانی جو روزمرہ چھوٹے واقعے کو بھی اہمیت دینا سکھاتی ہے۔","আমি ভেবেছিলাম সময় ঠিক হয়ে গেছে।":"میں نے سوچا تھا وقت طے ہو گیا۔","সম্পর্ক ও পরিস্থিতি অনুযায়ী তা বদলায়।":"تعلق اور صورتحال کے مطابق وہ بدلتا ہے۔","আমার মতে নির্দেশনা তৈরির সময় ব্যবহারকারীর দৃষ্টিকোণ জরুরি।":"میرے مطابق ہدایت بنانے کے وقت استعمال کنندہ کا نقطہ نظر ضروری۔","দীর্ঘ অভিজ্ঞতার ভিত্তিতে তিনি বোঝানোর ধরনে কৌশল ব্যবহার করেন।":"طویل تجربے کی بنیاد پر وہ سمجھانے کے انداز میں حکمت عملی استعمال کرتے ہیں۔","তাঁর মতে সবচেয়ে গুরুত্বপূর্ণ হলো গ্রাহকের কথা শোনা।":"ان کے مطابق سب سے اہم ہے گاہک کی بات سننا۔","আমি পাশের দোকানের ম্যানেজারের সাক্ষাৎকার নিয়েছি।":"میں نے پاس کی دکان کے منیجر کا انٹرویو لیا۔","জাপানিতে কোনো সময় না করার আগে কারণ বলা হয়।":"جاپانی میں کسی وقت نہ کرنے سے پہلے وجہ کہی جاتی ہے۔","না বুঝলে আমি ভদ্রভাবে নিশ্চিত হতে চাই।":"نہ سمجھوں تو میں شائستگی سے تصدیق چاہتا ہوں۔","আমিও অন্যের অবস্থান বিবেচনা করে কাজ করতে চাই বলে মনে হয়েছে।":"مجھے بھی دوسرے کے مقام کو مدنظر رکھ کر کام کرنا چاہتا ہوں لگا۔","তবে সবসময় একই প্রকাশ ব্যবহার হয় না।":"لیکن ہمیشہ وہی اظہار استعمال نہیں ہوتا۔","জাপানে নতুন আসার সময় এক বন্ধুর সঙ্গে কথা দেওয়া নিয়ে সমস্যায় পড়েছিলাম।":"جاپان نیا آنے کے وقت ایک دوست کے ساتھ وعدہ کرنے پر مشکل میں پڑا تھا۔","সাইকেল ব্যবহারকারীর তুলনায় ৭ জন বেশি।":"سائیکل استعمال کنندہ کے مقابلے میں 7 لوگ زیادہ۔","কারণ তথ্য বেশি হলেই অর্থ পরিষ্কার হয় এমন নয়।":"وجہ معلومات زیادہ ہو ہی تو مطلب واضح ہوتا ہے ایسا نہیں۔","তবে অল্পসংখ্যক ব্যক্তির ফল বলে এটি সামগ্রিক প্রবণতা নাও হতে পারে।":"لیکن کم تعداد افراد کا نتیجہ کہنے سے یہ مجموعی رجحان نہ بھی ہو سکتا ہے۔"},"study.writing_prompt":{"নিজের একটি ভুল বোঝাবুঝির অভিজ্ঞতা লিখুন: ঘটনা → নিজের ধারণা → অন্য পক্ষের অবস্থা → পরেরবার কী করবেন।":"اپنا ایک غلط فہمی کا تجربہ لکھیں: واقعہ → اپنی سمجھ → دوسرے فریق کی حالت → اگلی بار کیا کریں گے۔","বাংলা ও জাপানিতে কোনো অনুরোধ ফিরিয়ে দেওয়ার একটি করে উদাহরণ দিন। শব্দের অর্থ, সম্পর্ক ও পরিস্থিতি আলাদা করে লিখুন; জাতিগত সাধারণীকরণ এড়িয়ে চলুন।":"اردو اور جاپانی میں کوئی درخواست واپس کرنے کی ایک ایک مثال دیں۔ لفظ کا مطلب، تعلق اور صورتحال الگ کرکے لکھیں؛ قومی عام سازی سے پرہیز کریں۔","একটি গল্প বা সিনেমার সংক্ষিপ্ত রিভিউ লিখুন: পরিচয় → একটি দৃশ্য → নিজের অনুভূতি → সুপারিশের কারণ। সমাপ্তির সব তথ্য বলে দেবেন না।":"ایک کہانی یا فلم کا مختصر جائزہ لکھیں: تعارف → ایک منظر → اپنا احساس → تجویز کی وجہ۔ اختتام کی تمام معلومات نہ بتا دیں۔","এই কাল্পনিক সংখ্যাগুলো ব্যবহার করে চার বাক্যের প্রতিবেদন লিখুন। লক্ষ্যগোষ্ঠী → সবচেয়ে বড় অংশ → তুলনা → সিদ্ধান্তের সীমা।":"ان فرضی اعداد کو استعمال کرکے چار جملوں کی رپورٹ لکھیں۔ ہدف گروہ → سب سے بڑا حصہ → موازنہ → فیصلے کی حد۔","একটি ছোট সমস্যা বেছে ১৮০–২৫০ জাপানি অক্ষরে মতামত লিখুন: দাবি → কারণ → উদাহরণ → সম্ভাব্য আপত্তি → বাস্তব প্রস্তাব।":"ایک چھوٹا مسئلہ منتخب کرکے 180–250 جاپانی حروف میں رائے لکھیں: دعویٰ → وجہ → مثال → ممکنہ اعتراض → حقیقی تجویز۔","কোনো পরিচিত ব্যক্তির কাজ সম্পর্কে তিনটি প্রশ্ন করুন। সরাসরি উক্তি এবং নিজের উপলব্ধি আলাদা করে একটি ছোট প্রতিবেদন লিখুন।":"کسی واقف شخص کے کام کے بارے میں تین سوال کریں۔ براہ راست بیان اور اپنی سمجھ الگ کرکے ایک چھوٹی رپورٹ لکھیں۔"},"title":{"QUARTET II · বাংলা গ্রামার সহায়িকা":"QUARTET II · اردو گرامر رہنما"}},"qa":{"attr.aside@aria-label":{"পাঠ নির্বাচন":"سبق کا انتخاب"},"attr.div@aria-label":{"পড়ার ধরন":"پڑھنے کا انداز"},"attr.input@aria-label":{"গ্রামার খুঁজুন":"گرامر تلاش کریں"},"attr.meta@description":{"QUARTET Ⅱ-এর অধ্যায় ৭–১২-এর থিমে নির্বাচিত ৩৬টি বিষয়ে নিজস্ব বাংলা ব্যাখ্যা, ফুরিগানাসহ উদাহরণ ও অনুশীলন।":"QUARTET Ⅱ کے ابواب 7–12 کے موضوعات پر منتخب 36 موضوعات پر اپنی اردو وضاحت، فریگانا کے ساتھ مثالیں اور مشقیں۔"},"attr.nav@aria-label":{"এই অধ্যায়ের গ্রামার":"اس باب کی گرامر","QUARTET বই ও পড়ার ধরন":"QUARTET کتابیں اور پڑھنے کے انداز","পথ নির্দেশনা":"راستے کی رہنمائی"},"attr.progress@aria-label":{"গ্রামার শেখার অগ্রগতি":"گرامر سیکھنے کی پیش رفت"},"text.uncovered":{"পাঠ ও অনুশীলন খুলতে JavaScript চালু করুন।":"سبق اور مشق کھولنے کے لیے JavaScript فعال کریں۔","N2 Grammar পড়ুন":"N2 Grammar پڑھیں"}}};
